// CLASSICAL MECHANICS · KORTEWEG-DE VRIES & SOLITONS (06.7.x)

// 06.7.1: Single soliton: u(x,t) = −½c sech²[½√c (x − ct − x₀)]
// Slider over c shows amplitude ↔ speed ↔ width coupling.
export function KdvSoliton() {
  const [c, setC] = React.useState(2.0)
  const [tOff, setTOff] = React.useState(0.0)
  const nPts = 400
  const xMin = -10,
    xMax = 10
  const amp = 0.5 * c
  const yMin = -amp * 1.25 - 0.1
  const yMax = 0.2
  const pts = Array.from({ length: nPts }, (_, i) => {
    const x = xMin + (i / (nPts - 1)) * (xMax - xMin)
    const xi = x - c * tOff
    const s = 1 / Math.cosh(0.5 * Math.sqrt(c) * xi)
    return [x, -0.5 * c * s * s]
  })
  // Full width at half-depth: sech² = ½ at ξ = ±1.7627/√c, so width ∝ 1/√c.
  const center = c * tOff
  const halfW = 1.7627 / Math.sqrt(c)
  const yHalf = -0.25 * c
  return (
    <div>
      <Plot xRange={[xMin, xMax]} yRange={[yMin, yMax]} width={620} height={400}>
        <Axes step={2} showGrid={true} showTicks={true} />
        <Polyline points={pts} opacity={OPACITY.fg} strokeWidth={2} />
        {/* Width-at-half-depth marker: narrows as c grows */}
        <Polyline
          points={[
            [center - halfW, yHalf],
            [center + halfW, yHalf]
          ]}
          opacity={OPACITY.accent}
          strokeWidth={1.2}
        />
        <Dot x={center - halfW} y={yHalf} r={2.5} opacity={OPACITY.accent} />
        <Dot x={center + halfW} y={yHalf} r={2.5} opacity={OPACITY.accent} />
        <Tex
          at={[center + halfW + 0.2, yHalf]}
          tex={String.raw`\text{width}\propto 1/\sqrt{c}`}
          size={FONT_TINY}
          anchor="start"
          opacity={OPACITY.accent}
        />
        <Tex
          at={[xMin + 0.6, yMin * 0.85]}
          tex={String.raw`u_t-6uu_x+u_{xxx}=0`}
          size={FONT_LABEL}
          opacity={OPACITY.dim}
          anchor="start"
        />
        <Tex
          at={[0, yMin * 0.5]}
          tex={String.raw`u = -\tfrac{c}{2}\operatorname{sech}^2\!\left[\tfrac{\sqrt{c}}{2}(x-ct)\right]`}
          size={FONT_LABEL}
          opacity={OPACITY.dim}
          anchor="middle"
        />
        <Tex
          at={[xMax * 0.75, yMin * 0.15]}
          tex={String.raw`\text{amp}=-c/2`}
          size={FONT_LABEL}
          opacity={OPACITY.dim}
          anchor="middle"
        />
      </Plot>
      <Slider
        label="speed c"
        value={c}
        min={0.2}
        max={6}
        step={0.1}
        onChange={setC}
        format={v => v.toFixed(1)}
      />
      <Slider
        label="time t"
        value={tOff}
        min={-3}
        max={3}
        step={0.05}
        onChange={setTOff}
        format={v => v.toFixed(2)}
      />
    </div>
  )
}

// 06.7.2: Amplitude, speed, width: all three locked to c for the KdV soliton.
// Three curves plotted against c ∈ [0.1, 8]: amplitude c/2, speed c, width 4/√c.
export function KdvAmplitudeSpeedWidth() {
  const [cMark, setCMark] = React.useState(2.0)
  const nPts = 200
  const cMin = 0.1,
    cMax = 8
  const ampPts = Array.from({ length: nPts }, (_, i) => {
    const cv = cMin + (i / (nPts - 1)) * (cMax - cMin)
    return [cv, cv / 2]
  })
  const spdPts = Array.from({ length: nPts }, (_, i) => {
    const cv = cMin + (i / (nPts - 1)) * (cMax - cMin)
    return [cv, cv]
  })
  const widPts = Array.from({ length: nPts }, (_, i) => {
    const cv = cMin + (i / (nPts - 1)) * (cMax - cMin)
    return [cv, 4 / Math.sqrt(cv)]
  })
  const yMax = 9
  return (
    <div>
      <Plot xRange={[0, cMax]} yRange={[0, yMax]} width={620} height={440}>
        <Axes step={2} showGrid={true} showTicks={true} />
        <Polyline points={spdPts} opacity={OPACITY.fg} strokeWidth={1.8} />
        <Polyline
          points={ampPts}
          opacity={OPACITY.accent}
          strokeWidth={STROKE_PRIMARY}
          dash="6 3"
        />
        <Polyline points={widPts} opacity={OPACITY.dim} strokeWidth={1.2} dash="3 3" />
        <Dot x={cMark} y={cMark} r={5} opacity={OPACITY.fg} />
        <Dot x={cMark} y={cMark / 2} r={4} opacity={OPACITY.accent} />
        <Dot x={cMark} y={4 / Math.sqrt(cMark)} r={4} opacity={OPACITY.dim} />
        <Tex
          at={[cMax * 0.82, cMax * 0.82 * 1.05]}
          tex={String.raw`c\text{ (speed)}`}
          size={FONT_LABEL}
          opacity={OPACITY.fg}
          anchor="middle"
        />
        <Tex
          at={[cMax * 0.82, ((cMax * 0.82) / 2) * 1.15]}
          tex={String.raw`c/2\text{ (ampl.)}`}
          size={FONT_LABEL}
          opacity={OPACITY.accent}
          anchor="middle"
        />
        <Tex
          at={[cMax * 0.7, (4 / Math.sqrt(cMax * 0.7)) * 1.3]}
          tex={String.raw`4/\sqrt{c}\text{ (width)}`}
          size={FONT_LABEL}
          opacity={OPACITY.dim}
          anchor="middle"
        />
      </Plot>
      <Slider
        label="mark c"
        value={cMark}
        min={0.2}
        max={7.8}
        step={0.1}
        onChange={setCMark}
        format={v => v.toFixed(1)}
      />
    </div>
  )
}

// 06.7.3: Dispersion vs nonlinearity: two separate effects shown as curves.
// Linear dispersion: ω = −k³ (from linearised KdV u_t + u_xxx = 0).
// Nonlinear steepening rate (proxy): for a wave of amplitude a, effective speed shift ≈ 6a·k.
// Slider over amplitude a shows how nonlinearity grows with a.
export function KdvDispersionVsNonlinearity() {
  const [a, setA] = React.useState(0.3)
  const nPts = 300
  const kMin = 0.01,
    kMax = 3.5
  const disp = k => k * k * k // |ω| = k³ from linear KdV u_t + u_xxx = 0
  const nl = k => 6 * a * k // steepening rate ∝ 6ak for amplitude a
  const dispPts = Array.from({ length: nPts }, (_, i) => {
    const k = kMin + (i / (nPts - 1)) * (kMax - kMin)
    return [k, disp(k)]
  })
  const nlPts = Array.from({ length: nPts }, (_, i) => {
    const k = kMin + (i / (nPts - 1)) * (kMax - kMin)
    return [k, nl(k)]
  })
  const yMax = Math.max(disp(kMax), nl(kMax)) * 1.08
  // balance occurs where k³ = 6ak → k² = 6a → k = √(6a)
  const kB = Math.sqrt(6 * a)
  const kBin = kB > kMin && kB < kMax
  // Shade the lens between the two rate curves: nonlinearity wins for k<k*,
  // dispersion wins for k>k*. The crossing is the only wavenumber that balances.
  const lensBot = dispPts.map(([k]) => [k, Math.min(disp(k), nl(k))])
  const lensTop = dispPts.map(([k]) => [k, Math.max(disp(k), nl(k))]).reverse()
  const lensFill = lensBot.concat(lensTop)

  // Companion: the soliton this balance actually produces. The KdV soliton of
  // amplitude a is u(ξ) = −a·sech²(√(a/2)·ξ); larger a ⇒ stronger steepening ⇒
  // a narrower, deeper pulse (width ∝ 1/√a). Computed exactly, not schematic.
  const sMin = -6,
    sMax = 6
  const kw = Math.sqrt(a / 2)
  const solPts = Array.from({ length: 300 }, (_, i) => {
    const xi = sMin + (i / 299) * (sMax - sMin)
    const s = 1 / Math.cosh(kw * xi)
    return [xi, -a * s * s]
  })
  const halfWidth = 1 / kw // characteristic half-width (units of ξ)
  return (
    <div>
      <Plot xRange={[0, kMax]} yRange={[0, yMax]} width={620} height={400}>
        <Axes step={1} showGrid={true} showTicks={true} />
        <Polyline points={lensFill} closed opacity={0} fill={FG} fillOpacity={OPACITY.hair} />
        <Polyline points={dispPts} opacity={OPACITY.fg} strokeWidth={1.8} />
        <Polyline points={nlPts} opacity={OPACITY.accent} strokeWidth={STROKE_PRIMARY} dash="6 3" />
        {kBin && (
          <Polyline
            points={[
              [kB, 0],
              [kB, disp(kB)]
            ]}
            opacity={OPACITY.dim}
            dash="2 3"
          />
        )}
        {kBin && <Dot x={kB} y={disp(kB)} r={5} opacity={OPACITY.fg} />}
        <Tex
          at={[kMax * 0.62, disp(kMax * 0.62) * 0.92]}
          tex={String.raw`k^3\ \text{disperse}`}
          size={FONT_LABEL}
          opacity={OPACITY.fg}
          anchor="end"
        />
        <Tex
          at={[kMax * 0.97, nl(kMax) * 0.78]}
          tex={String.raw`\sim 6ak\ \text{steepen}`}
          size={FONT_LABEL}
          opacity={OPACITY.accent}
          anchor="end"
        />
        {kBin && (
          <Tex
            at={[kB, disp(kB) + yMax * 0.13]}
            tex={String.raw`k^*=\sqrt{6a}=${kB.toFixed(2)}`}
            size={FONT_LABEL}
            opacity={OPACITY.dim}
            anchor="middle"
          />
        )}
        <Tex
          at={[kMin + 0.05, yMax * 0.94]}
          tex={String.raw`\text{balance}\Rightarrow\text{soliton}`}
          size={FONT_LABEL}
          opacity={OPACITY.dim}
          anchor="start"
        />
      </Plot>
      <Plot xRange={[sMin, sMax]} yRange={[-1.62, 0.32]} width={620} height={280}>
        <Axes step={2} showGrid={true} showTicks={false} />
        <Polyline points={solPts} opacity={OPACITY.fg} strokeWidth={2} />
        <Polyline
          points={[
            [-halfWidth, -a / 2],
            [halfWidth, -a / 2]
          ]}
          opacity={OPACITY.dim}
          dash="3 3"
        />
        <Tex
          at={[sMax * 0.96, -0.18]}
          tex={`u=-a\\,\\mathrm{sech}^2\\!\\big(\\sqrt{\\tfrac{a}{2}}\\,\\xi\\big)`}
          size={FONT_LABEL}
          opacity={OPACITY.fg}
          anchor="end"
        />
        <Tex
          at={[0, -a - 0.18]}
          tex={String.raw`\text{depth }a,\ \text{width}\propto 1/\sqrt{a}`}
          size={FONT_SMALL}
          opacity={OPACITY.dim}
          anchor="middle"
        />
      </Plot>
      <Slider
        label="amplitude a"
        value={a}
        min={0.02}
        max={1.5}
        step={0.02}
        onChange={setA}
        format={v => v.toFixed(2)}
      />
    </div>
  )
}

// 06.7.4: Cnoidal wave: f(ξ) = f₂ − (f₂−f₃) cn²[...| m], m ∈ [0,1].
// For m → 0: cn(v|0) → cos(v), gives cosine wave.
// For m → 1: cn(v|1) → sech(v), gives soliton train.
// We implement cn via the AGM/Landen accurate approximation for general m.
// K(m) computed by AGM.
function agmK(m) {
  if (m >= 1) return Infinity
  let a = 1,
    b = Math.sqrt(1 - m)
  for (let i = 0; i < 20; i++) {
    const an = (a + b) / 2
    const bn = Math.sqrt(a * b)
    if (Math.abs(an - bn) < 1e-12) break
    a = an
    b = bn
  }
  return Math.PI / (2 * a)
}
// Jacobi cn(u | m) via descending Landen transforms + AGM
function jacobi_cn(u, m) {
  if (m < 1e-10) return Math.cos(u)
  if (m > 1 - 1e-10) return 1 / Math.cosh(u)
  // Use series of Landen descending transforms
  const N = 10
  const ks = [Math.sqrt(m)]
  for (let i = 1; i < N; i++) {
    const kp =
      (1 - Math.sqrt(1 - ks[i - 1] * ks[i - 1])) / (1 + Math.sqrt(1 - ks[i - 1] * ks[i - 1]))
    ks.push(kp)
    if (kp < 1e-12) break
  }
  let phi = Math.pow(2, ks.length - 1) * ks[ks.length - 1] * u
  for (let i = ks.length - 2; i >= 0; i--) {
    phi = (phi + Math.asin(ks[i] * Math.sin(phi))) / 2
  }
  return Math.cos(phi)
}
export function KdvCnoidalWave() {
  const [m, setM] = React.useState(0.6)
  // Roots f1=0, f3=-1, f2 = f3 + m(f1-f3) = -1 + m. Profile oscillates between
  // trough f3 (at cn=1) and crest f2 (at cn=0); amplitude = f2 - f3 = m.
  const f1 = 0,
    f3 = -1
  const f2 = f3 + m * (f1 - f3) // = -1 + m
  const amp = f2 - f3 // = m
  const mid = (f2 + f3) / 2
  const Km = agmK(m)
  const period = 2 * Km * Math.sqrt(2 / (f1 - f3)) // spatial period of cn²
  const nPts = 420
  const xSpan = Math.min(period * 2.5, 30)
  const xMin = -xSpan / 2,
    xMax = xSpan / 2
  const ampShow = Math.max(amp, 0.06)
  const sx = i => xMin + (i / (nPts - 1)) * (xMax - xMin)
  const pts = Array.from({ length: nPts }, (_, i) => {
    const xi = sx(i)
    const arg = xi * Math.sqrt((f1 - f3) / 2)
    const cn = jacobi_cn(arg, m)
    return [xi, f2 - (f2 - f3) * cn * cn]
  })
  // Reference sinusoid: same amplitude and period, trough at ξ=0. The cnoidal
  // curve sits on this for small m and departs into sharp humps as m → 1.
  const cosPts = Array.from({ length: nPts }, (_, i) => {
    const xi = sx(i)
    return [xi, mid - (amp / 2) * Math.cos((2 * Math.PI * xi) / period)]
  })
  const yMin = f3 - 0.3 * ampShow
  const yMax = f2 + 0.78 * ampShow
  const crest = period / 2 // crests sit half a period either side of the ξ=0 trough
  const inRange = crest < xMax
  return (
    <div>
      <Plot xRange={[xMin, xMax]} yRange={[yMin, yMax]} width={620} height={440}>
        <Axes step={5} showGrid={true} showTicks={true} />
        {/* crest / trough guide lines */}
        <Polyline
          points={[
            [xMin, f2],
            [xMax, f2]
          ]}
          opacity={OPACITY.faint}
          dash="2 4"
        />
        <Polyline
          points={[
            [xMin, f3],
            [xMax, f3]
          ]}
          opacity={OPACITY.faint}
          dash="2 4"
        />
        {/* one wavelength, crest to crest */}
        {inRange && (
          <>
            <Polyline
              points={[
                [-crest, yMin],
                [-crest, f2]
              ]}
              opacity={OPACITY.dim}
              dash="1 4"
            />
            <Polyline
              points={[
                [crest, yMin],
                [crest, f2]
              ]}
              opacity={OPACITY.dim}
              dash="1 4"
            />
            <Tex
              at={[0, yMin + 0.12 * ampShow]}
              tex={String.raw`\lambda=${period.toFixed(2)}`}
              size={FONT_SMALL}
              opacity={OPACITY.dim}
              anchor="middle"
            />
          </>
        )}
        <Polyline
          points={cosPts}
          opacity={OPACITY.faint}
          strokeWidth={STROKE_SECONDARY}
          dash="4 4"
        />
        <Polyline points={pts} opacity={OPACITY.fg} strokeWidth={2} />
        <Tex
          at={[xMin * 0.92, f2 + 0.6 * ampShow]}
          tex={String.raw`m=${m.toFixed(3)}`}
          size={FONT_LABEL}
          opacity={OPACITY.fg}
          anchor="start"
        />
        <Tex
          at={[xMax * 0.92, f2 + 0.6 * ampShow]}
          tex={String.raw`\mathrm{cn}^2\ \text{wave}`}
          size={FONT_LABEL}
          opacity={OPACITY.dim}
          anchor="end"
        />
        <Tex
          at={[xMax * 0.92, f2 + 0.18 * ampShow]}
          tex={String.raw`m\!\to\!0:\ \cos\quad m\!\to\!1:\ \mathrm{sech}^2`}
          size={FONT_TINY}
          opacity={OPACITY.dim}
          anchor="end"
        />
      </Plot>
      <Slider
        label="modulus m"
        value={m}
        min={0.01}
        max={0.999}
        step={0.01}
        onChange={setM}
        format={v => v.toFixed(3)}
      />
    </div>
  )
}

// 06.7.5: Conservation laws of KdV: the first four integrals I_{-1}…I_2.
// Plots the integrand of each I_s evaluated on the soliton profile u(x) = −½c sech²(½√c x).
// Slider over c shows how each density changes.
export function KdvConservationLaws() {
  const [c, setC] = React.useState(2.0)
  const nPts = 400
  const xMin = -12,
    xMax = 12
  const xs = Array.from({ length: nPts }, (_, i) => xMin + (i / (nPts - 1)) * (xMax - xMin))
  // Soliton u = −½c sech²(½√c x) with exact analytic derivatives.
  const rows = xs.map(x => {
    const k = 0.5 * Math.sqrt(c)
    const s = 1 / Math.cosh(k * x)
    const th = Math.tanh(k * x)
    const u = -0.5 * c * s * s
    const up = c * k * s * s * th // u' = c k sech² tanh
    const upp = c * k * k * s * s * (3 * s * s - 2) // u'' = c k² sech² (3 sech² − 2)
    return { x, u, up, upp }
  })
  // The first four conserved densities: each led by a higher power of u.
  const dens = [
    {
      f: r => r.u,
      label: String.raw`\rho_{-1}=u`,
      power: '∝u',
      op: OPACITY.fg,
      dash: undefined,
      w: 1.9
    },
    {
      f: r => r.u * r.u,
      label: String.raw`\rho_0=u^2`,
      power: '∝u²',
      op: OPACITY.accent,
      dash: '6 3',
      w: 1.5
    },
    {
      f: r => (r.up * r.up) / 2 + r.u * r.u * r.u,
      label: String.raw`\rho_1=\tfrac{(u')^2}{2}+u^3`,
      power: '∝u³',
      op: OPACITY.dim,
      dash: '2 3',
      w: 1.5
    },
    {
      f: r => (r.upp * r.upp) / 2 - 2.5 * r.u * r.u * r.upp + 2.5 * r.u * r.u * r.u * r.u,
      label: String.raw`\rho_2=\tfrac{(u'')^2}{2}-\tfrac{5}{2}u^2u''+\tfrac{5}{2}u^4`,
      power: '∝u⁴',
      op: OPACITY.dim,
      dash: '1 4',
      w: 1.7
    }
  ]
  // Scale each density to common peak height so the power-ladder shape is legible.
  const series = dens.map(d => {
    const raw = rows.map(r => d.f(r))
    const peak = Math.max(1e-9, ...raw.map(Math.abs))
    return rows.map((r, i) => [r.x, raw[i] / peak])
  })
  return (
    <div>
      <Plot xRange={[xMin, xMax]} yRange={[-1.3, 1.55]} width={620} height={440}>
        <Axes step={4} showGrid={true} showTicks={true} />
        {series.map((pts, i) => (
          <Polyline
            key={i}
            points={pts}
            opacity={dens[i].op}
            strokeWidth={dens[i].w}
            dash={dens[i].dash}
          />
        ))}
        {dens.map((d, i) => (
          <Tex
            key={i}
            at={[xMin + 0.6, 1.42 - i * 0.62]}
            tex={d.label}
            size={FONT_SMALL}
            opacity={d.op}
            anchor="start"
          />
        ))}
        <Tex
          at={[xMax - 0.6, 1.42]}
          tex={String.raw`u\to u^2\to u^3\to u^4`}
          size={FONT_LABEL}
          opacity={OPACITY.dim}
          anchor="end"
        />
        <Tex
          at={[xMax - 0.6, 1.16]}
          tex={String.raw`u_t-6uu_x+u_{xxx}=0`}
          size={FONT_SMALL}
          opacity={OPACITY.dim}
          anchor="end"
        />
      </Plot>
      <Slider
        label="speed c"
        value={c}
        min={0.5}
        max={5}
        step={0.1}
        onChange={setC}
        format={v => v.toFixed(1)}
      />
    </div>
  )
}

// 06.7.6: KdvCubicZeroCases: cubic F(f) = (f-f1)(f-f2)(f-f3).
// Slider p merges roots: cnoidal (3 simple zeros) to soliton (double+simple).
export function KdvCubicZeroCases() {
  const [p, setP] = React.useState(0.5)
  // F(f) = (f - f1)(f - f2)(f - f3), with f1 = 0 (top) and f3 = -2 (bottom) fixed.
  // f2 = -2 + 2p slides up between them. Bounded travelling waves live where
  // F ≤ 0 on the upper interval [f2, f1]: the wave oscillates between trough f2
  // and crest f1. The soliton is the homoclinic limit where f2 → f3 (lower roots
  // merge, period → ∞). When f2 → f1 the amplitude → 0: the harmonic limit, NOT
  // a soliton.
  const f1 = 0
  const f3 = -2
  const f2 = f3 + p * (f1 - f3) // = -2 + 2p
  const F = f => (f - f1) * (f - f2) * (f - f3)
  const nPts = 400
  const fMin = -2.6,
    fMax = 0.6
  const cubic = Array.from({ length: nPts }, (_, i) => {
    const fv = fMin + (i / (nPts - 1)) * (fMax - fMin)
    return [fv, F(fv)]
  })
  const yMin = -2.5,
    yMax = 2.5
  const band = [
    [f2, yMin],
    [f1, yMin],
    [f1, yMax],
    [f2, yMax]
  ]
  // Companion travelling-wave profile from the same three roots.
  const mm = (f1 - f2) / (f1 - f3) // elliptic parameter m² = 1 - p
  const Km = agmK(mm)
  const periodX = 2 * Km // since √((f1-f3)/2) = 1 here
  const amp = f1 - f2
  const span2 = Math.min(periodX * 2.2, 24)
  const wave = Array.from({ length: 360 }, (_, i) => {
    const xi = -span2 / 2 + (i / 359) * span2
    const arg = xi * Math.sqrt((f1 - f3) / 2)
    const cn = jacobi_cn(arg, mm)
    return [xi, f2 + (f1 - f2) * cn * cn]
  })
  let waveLabel, regime
  if (p < 0.05) {
    regime = String.raw`\text{soliton: }f_2,f_3\text{ merge }(m\!\to\!1)`
    waveLabel = String.raw`\text{single sech}^2\text{ hump}`
  } else if (p > 0.95) {
    regime = String.raw`\text{harmonic limit: amplitude}\to 0`
    waveLabel = String.raw`\cos\text{-like, vanishing}`
  } else {
    regime = String.raw`\text{cnoidal: 3 simple roots}`
    waveLabel = String.raw`\text{oscillates }f_2\!\leftrightarrow\!f_1`
  }
  return (
    <div>
      <Plot xRange={[fMin, fMax]} yRange={[yMin, yMax]} width={620} height={400}>
        <Axes step={1} showGrid={true} showTicks={true} />
        {amp > 1e-3 && (
          <Polyline points={band} closed opacity={0} fill={FG} fillOpacity={OPACITY.hair} />
        )}
        <Polyline points={cubic} opacity={OPACITY.fg} strokeWidth={2} />
        <Dot x={f1} y={0} r={5} opacity={OPACITY.fg} />
        <Dot x={f2} y={0} r={5} opacity={OPACITY.accent} />
        <Dot x={f3} y={0} r={5} opacity={OPACITY.dim} />
        <Tex
          at={[f1, 0.34]}
          tex={String.raw`f_1`}
          size={FONT_LABEL}
          opacity={OPACITY.fg}
          anchor="middle"
        />
        <Tex
          at={[f2, -0.5]}
          tex={String.raw`f_2`}
          size={FONT_LABEL}
          opacity={OPACITY.accent}
          anchor="middle"
        />
        <Tex
          at={[f3, 0.34]}
          tex={String.raw`f_3`}
          size={FONT_LABEL}
          opacity={OPACITY.dim}
          anchor="middle"
        />
        <Tex
          at={[fMin + 0.1, yMax * 0.85]}
          tex={String.raw`F(f)`}
          size={FONT_LABEL}
          opacity={OPACITY.fg}
          anchor="start"
        />
        <Tex
          at={[fMax - 0.05, yMax * 0.85]}
          tex={regime}
          size={FONT_SMALL}
          opacity={OPACITY.dim}
          anchor="end"
        />
      </Plot>
      <Plot xRange={[-span2 / 2, span2 / 2]} yRange={[-2.3, 0.5]} width={620} height={280}>
        <Axes step={4} showGrid={true} showTicks={false} />
        <Polyline
          points={[
            [-span2 / 2, f1],
            [span2 / 2, f1]
          ]}
          opacity={OPACITY.faint}
          dash="2 4"
        />
        <Polyline
          points={[
            [-span2 / 2, f2],
            [span2 / 2, f2]
          ]}
          opacity={OPACITY.faint}
          dash="2 4"
        />
        <Polyline points={wave} opacity={OPACITY.fg} strokeWidth={2} />
        <Tex
          at={[(span2 / 2) * 0.96, 0.28]}
          tex={`f(\\xi)`}
          size={FONT_LABEL}
          opacity={OPACITY.fg}
          anchor="end"
        />
        <Tex
          at={[0, -2.06]}
          tex={waveLabel}
          size={FONT_SMALL}
          opacity={OPACITY.dim}
          anchor="middle"
        />
      </Plot>
      <Slider
        label="merge p  (0 = soliton, 1 = harmonic)"
        value={p}
        min={0}
        max={1}
        step={0.01}
        onChange={setP}
        format={v => v.toFixed(2)}
      />
    </div>
  )
}

// 06.7.7: KdvTwoSolitonCollision: exact two-soliton solution via Hirota tau function.
// u = 2 ∂²_x ln τ,  τ = 1 + e^{η1} + e^{η2} + A12² e^{η1+η2}
// ηi = ki x − ki³ t,  A12 = (k1−k2)/(k1+k2).
// Slider moves time through the collision.
export function KdvTwoSolitonCollision() {
  const [playing, setPlaying] = React.useState(true)
  const [tManual, setTManual] = React.useState(-6.0)
  const k1 = 1.5,
    k2 = 0.8
  const tMax = 8
  const tFit = 5 // fit/measure time: at ±tMax the fast soliton sits outside the window
  const A12sq = Math.pow((k1 - k2) / (k1 + k2), 2)
  // Hirota phase shifts Δx_i = ∓ ln(A₁₂²)/k_i: fast forward, slow back.
  const dTheory1 = -Math.log(A12sq) / k1
  const dTheory2 = Math.log(A12sq) / k2
  const nPts = 600
  const xMin = -18,
    xMax = 18
  const dx = (xMax - xMin) / (nPts - 1)
  const eps = 1e-4
  const amp1 = (k1 * k1) / 2,
    amp2 = (k2 * k2) / 2
  const lnTau = (x, tv) => {
    const e1 = Math.exp(k1 * x - k1 * k1 * k1 * tv)
    const e2 = Math.exp(k2 * x - k2 * k2 * k2 * tv)
    return Math.log(1 + e1 + e2 + A12sq * e1 * e2)
  }
  const uval = (x, tv) =>
    (2 * (lnTau(x + eps, tv) - 2 * lnTau(x, tv) + lnTau(x - eps, tv))) / (eps * eps)
  const uAt = tv => Array.from({ length: nPts }, (_, i) => [xMin + i * dx, uval(xMin + i * dx, tv)])
  // The two largest local maxima, returned sorted by height (tallest first = k1).
  const peaks = arr => {
    const loc = []
    for (let i = 2; i < arr.length - 2; i++) {
      if (arr[i][1] > arr[i - 1][1] && arr[i][1] >= arr[i + 1][1] && arr[i][1] > 0.05)
        loc.push(arr[i])
    }
    loc.sort((a, b) => b[1] - a[1])
    return loc.slice(0, 2)
  }
  // Free-soliton trajectories fitted to the incoming (t = −tMax) state; their gap
  // from the actual peaks after the collision IS the phase shift: measured, not
  // assumed, straight from the exact τ-function.
  const fit = React.useMemo(() => {
    const inc = peaks(uAt(-tFit))
    if (inc.length < 2) return { x10: 0, x20: 0, d1: 0, d2: 0 }
    const x10 = inc[0][0] - k1 * k1 * -tFit
    const x20 = inc[1][0] - k2 * k2 * -tFit
    const out = peaks(uAt(tFit))
    const o1 = out.length > 0 ? out[0][0] : k1 * k1 * tFit + x10
    const o2 = out.length > 1 ? out[1][0] : k2 * k2 * tFit + x20
    return { x10, x20, d1: o1 - (k1 * k1 * tFit + x10), d2: o2 - (k2 * k2 * tFit + x20) }
  }, [])
  const aniT = useAnimationTime(playing, 1)
  // Loop time from −tMax to +tMax at 2.2 units/s.
  const t = playing ? -tMax + ((aniT * 2.2) % (2 * tMax)) : tManual
  const ghost = (tv, amp, k, x0) =>
    Array.from({ length: 360 }, (_, i) => {
      const x = xMin + (i / 359) * (xMax - xMin)
      const s = 1 / Math.cosh((k / 2) * (x - (k * k * tv + x0)))
      return [x, amp * s * s]
    })
  const pts = uAt(t)
  const g1 = ghost(t, amp1, k1, fit.x10)
  const g2 = ghost(t, amp2, k2, fit.x20)
  const yMax = Math.max(amp1, amp2) * 1.35
  return (
    <div>
      <Plot xRange={[xMin, xMax]} yRange={[-0.2, yMax]} width={620} height={440}>
        <Axes step={4} showGrid={true} showTicks={true} />
        <Polyline points={g1} opacity={OPACITY.faint} strokeWidth={STROKE_SECONDARY} dash="3 3" />
        <Polyline points={g2} opacity={OPACITY.faint} strokeWidth={STROKE_SECONDARY} dash="3 3" />
        <Polyline points={pts} opacity={OPACITY.fg} strokeWidth={2} />
        <Tex
          at={[xMax - 0.5, yMax * 0.9]}
          tex={String.raw`u_t+6uu_x+u_{xxx}=0:\quad u=2\,\partial_x^2\ln\tau`}
          size={FONT_LABEL}
          opacity={OPACITY.dim}
          anchor="end"
        />
        <Tex
          at={[xMin + 0.5, yMax * 0.9]}
          tex={String.raw`\text{dashed = free (no collision)}`}
          size={FONT_SMALL}
          opacity={OPACITY.dim}
          anchor="start"
        />
      </Plot>

      {/* Readout row: measured post-collision shifts vs the Hirota prediction */}
      <div
        style={{
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          gap: 28,
          flexWrap: 'wrap',
          marginTop: 12
        }}
      >
        <span
          style={{
            display: 'inline-flex',
            alignItems: 'center',
            gap: 8,
            fontSize: FONT_TEX,
            opacity: OPACITY.fg
          }}
        >
          <KatexInline tex={String.raw`\Delta x_{\text{fast}}`} />
          <span style={{ fontVariantNumeric: 'tabular-nums', fontSize: FONT_CONTROL }}>
            {`${fit.d1 >= 0 ? '+' : ''}${fit.d1.toFixed(2)}`}
          </span>
        </span>
        <span
          style={{
            display: 'inline-flex',
            alignItems: 'center',
            gap: 8,
            fontSize: FONT_TEX,
            opacity: OPACITY.accent
          }}
        >
          <KatexInline tex={String.raw`\Delta x_{\text{slow}}`} />
          <span style={{ fontVariantNumeric: 'tabular-nums', fontSize: FONT_CONTROL }}>
            {`${fit.d2 >= 0 ? '+' : ''}${fit.d2.toFixed(2)}`}
          </span>
        </span>
        <span
          style={{
            display: 'inline-flex',
            alignItems: 'center',
            gap: 8,
            fontSize: FONT_TEX,
            opacity: OPACITY.dim
          }}
        >
          <KatexInline
            tex={String.raw`\text{Hirota }\mp\tfrac{\ln A_{12}^2}{k_i}:\ ${dTheory1 >= 0 ? '+' : ''}${dTheory1.toFixed(2)},\ ${dTheory2.toFixed(2)}`}
          />
        </span>
      </div>
      <PlayPause
        playing={playing}
        onToggle={() => setPlaying(p => !p)}
        onReset={() => {
          setPlaying(false)
          setTManual(-tMax)
        }}
        label="collision"
      />
      <Slider
        label="time t"
        value={t}
        min={-tMax}
        max={tMax}
        step={0.1}
        onChange={v => {
          setPlaying(false)
          setTManual(v)
        }}
        format={v => (v >= 0 ? '+' : '') + v.toFixed(1)}
      />
    </div>
  )
}

// CLASSICAL MECHANICS · SINE-GORDON & SOLITONS (06.8.x)

// 06.8.1 : SgPendulumChain: chain of N torsion-coupled pendula showing the kink
// (one full 2 pi twist). Angle at each site is the exact static kink profile
// u(x) = 4*arctan(e^(gamma*(x-x0))), monotonic 0 -> 2 pi with u = pi at the center x0.
// The rotation is drawn in an oblique (elliptical) projection: small horizontal
// radius rx, tall vertical radius ry. This shows the twist as a clean corkscrew and
// keeps neighbouring bobs from crossing (rx < pivot spacing). Brightness tracks the
// sine-Gordon energy density sech^2(gamma*(x-x0)), so the lit band IS the soliton and
// it slides with the kink-position slider.
export function SgPendulumChain() {
  const [x0, setX0] = React.useState(0)
  const N = 31
  const L = 14
  const gamma = 1 // static kink: width parameter is exactly 1 in natural units
  const xs = Array.from({ length: N }, (_, i) => -L / 2 + (i / (N - 1)) * L)
  const angles = xs.map(x => 4 * Math.atan(Math.exp(gamma * (x - x0))))
  // localized energy density sech^2 -> brightness weight in [0,1]
  const weights = xs.map(x => {
    const c = Math.cosh(gamma * (x - x0))
    return 1 / (c * c)
  })
  const W = 660,
    H = 300
  const ML = 46,
    MR = 46
  const pivotY = H * 0.46
  const xScale = x => ML + ((x + L / 2) / L) * (W - ML - MR)
  const spacing = (W - ML - MR) / (N - 1)
  const rx = spacing * 0.55 // horizontal (foreshortened) radius: < spacing, no crossing
  const ry = H * 0.3 // vertical radius: fills the frame
  const tips = xs.map((x, i) => {
    const px = xScale(x)
    const a = angles[i]
    // u = 0 hangs down (+y), u = pi points up (-y); foreshortened sideways component
    return [px + rx * Math.sin(a), pivotY + ry * Math.cos(a)]
  })
  const kinkX = xScale(x0)
  const labelStyle = {
    textTransform: 'uppercase'
  }
  // energy-density strip (drawn below): e(x) = sech^2(gamma (x - x0)) on a smooth grid,
  // x-aligned with the chain above so its peak sits under the brightest pendula.
  const eBaseY = 60,
    eAmpY = 46
  const eStrip = Array.from({ length: 161 }, (_, i) => {
    const x = -L / 2 + (i / 160) * L
    const c = Math.cosh(gamma * (x - x0))
    return [xScale(x), eBaseY - eAmpY / (c * c)]
  })
  const eLineStrip = eStrip.map(p => `${p[0].toFixed(2)},${p[1].toFixed(2)}`).join(' ')
  const eFillStrip =
    `${xScale(-L / 2).toFixed(2)},${eBaseY} ` +
    eLineStrip +
    ` ${xScale(L / 2).toFixed(2)},${eBaseY}`
  return (
    <div>
      <svg
        viewBox={`0 0 ${W} ${H}`}
        width="100%"
        preserveAspectRatio="xMidYMid meet"
        style={{ display: 'block', color: 'var(--text-primary)' }}
      >
        {/* torsion rod: the coupling axis the pendula hang from */}
        <line
          x1={xScale(xs[0])}
          y1={pivotY}
          x2={xScale(xs[N - 1])}
          y2={pivotY}
          stroke={FG}
          strokeOpacity={OPACITY.dim}
          strokeWidth={STROKE_SECONDARY}
        />
        {/* kink-centre guide: moves with the slider */}
        <line
          x1={kinkX}
          y1={pivotY - ry - 10}
          x2={kinkX}
          y2={pivotY + ry + 6}
          stroke={FG}
          strokeOpacity={OPACITY.faint}
          strokeWidth={STROKE_SECONDARY}
          strokeDasharray="3 4"
        />
        {/* bob-tip helix trace: the 2 pi twist made visible as one corkscrew */}
        <polyline
          points={tips.map(t => `${t[0].toFixed(2)},${t[1].toFixed(2)}`).join(' ')}
          fill="none"
          stroke={FG}
          strokeOpacity={0.28}
          strokeWidth={1.2}
        />
        {/* pendula: angle from the exact kink profile, brightness ~ sech^2 energy density */}
        {xs.map((x, i) => {
          const px = xScale(x)
          const [bx, by] = tips[i]
          const w = weights[i]
          const op = OPACITY.dim + (OPACITY.fg - OPACITY.dim) * w
          return (
            <g key={i}>
              <line
                x1={px}
                y1={pivotY}
                x2={bx}
                y2={by}
                stroke={FG}
                strokeOpacity={op}
                strokeWidth={0.9 + 1.5 * w}
              />
              <circle cx={px} cy={pivotY} r={1.3} fill={FG} fillOpacity={OPACITY.dim} />
              <circle cx={bx} cy={by} r={3 + 2 * w} fill={FG} fillOpacity={op} />
            </g>
          )
        })}
        {/* vacuum labels: bobs hang straight down at both ends */}
        <text
          x={ML + 16}
          y={pivotY + ry + 22}
          fill={FG}
          fontSize={FONT_SMALL}
          opacity={OPACITY.dim}
          letterSpacing={LS_OPEN}
          textAnchor="start"
          style={labelStyle}
        >
          u = 0
        </text>
        <TexPx
          x={W - MR - 16}
          y={pivotY + ry + 22}
          anchor="end"
          tex={'u = 2\\pi'}
          size={FONT_SMALL}
          opacity={OPACITY.dim}
        />
        {/* kink centre: pendulum points straight up at u = pi */}
        <TexPx
          x={kinkX}
          y={pivotY - ry - 16}
          anchor="middle"
          tex={'u = \\pi'}
          size={FONT_SMALL}
          opacity={OPACITY.accent}
        />
      </svg>
      {/* energy-density strip: names what the bob brightness above encodes */}
      <svg
        viewBox={`0 0 ${W} 72`}
        width="100%"
        preserveAspectRatio="xMidYMid meet"
        style={{ display: 'block', color: 'var(--text-primary)', marginTop: 2 }}
      >
        <line
          x1={kinkX}
          y1={2}
          x2={kinkX}
          y2={eBaseY + 2}
          stroke={FG}
          strokeOpacity={OPACITY.faint}
          strokeWidth={STROKE_SECONDARY}
          strokeDasharray="3 4"
        />
        <polyline points={eFillStrip} fill={FG} fillOpacity={0.07} stroke="none" />
        <polyline
          points={eLineStrip}
          fill="none"
          stroke={FG}
          strokeOpacity={OPACITY.accent}
          strokeWidth={STROKE_PRIMARY}
        />
        <TexPx
          x={ML}
          y={14}
          anchor="start"
          tex={'\\text{energy density}\\propto\\mathrm{sech}^2'}
          size={FONT_TINY}
          opacity={OPACITY.dim}
          width={242}
        />
      </svg>
      <Slider
        label="kink position"
        value={x0}
        min={-4}
        max={4}
        step={0.1}
        onChange={setX0}
        format={v => v.toFixed(1)}
      />
    </div>
  )
}

// 06.8.2 : SgKink: the boosted sine-Gordon kink at t = 0 and its gradient.
// Field  u(x) = 4 arctan(e^{gamma x}) climbs 0 -> 2pi; gradient u_x = 2 gamma sech(gamma x)
// is the localized soliton lump. The velocity slider sets gamma = 1/sqrt(1-v^2): as
// v -> 1 the kink Lorentz-contracts: its width shrinks by sqrt(1-v^2), so the field
// steepens and the gradient lump narrows and peaks higher at 2 gamma, yet always
// encloses the same 2pi twist (the conserved topological charge). A faint ghost holds
// the v = 0 rest shape for comparison. Both curves are sampled from the closed forms.
// At t = 0 the profile depends only on |v|, so the control runs 0 -> 0.95.
export function SgKink() {
  const [v, setV] = React.useState(0)
  const gamma = 1 / Math.sqrt(1 - v * v + 1e-12)
  const TWO_PI = 2 * Math.PI
  const xMin = -8,
    xMax = 8
  const nPts = 700
  const xs = Array.from({ length: nPts }, (_, i) => xMin + (i / (nPts - 1)) * (xMax - xMin))
  const kink = g => xs.map(x => [x, 4 * Math.atan(Math.exp(g * x))])
  const grad = g => xs.map(x => [x, (2 * g) / Math.cosh(g * x)])
  const kinkRest = kink(1)
  const kinkNow = kink(gamma)
  const gradRest = grad(1)
  const gradNow = grad(gamma)
  const peak = 2 * gamma
  const gradArea = [[xMin, 0], ...gradNow, [xMax, 0]]

  const readout = { display: 'inline-flex', alignItems: 'center', gap: 8, fontSize: FONT_TEX }
  const num = { fontVariantNumeric: 'tabular-nums', fontSize: FONT_CONTROL }

  return (
    <div>
      {/* FIELD panel: the kink climbs 0 -> 2pi; ghost = rest shape (v = 0) */}
      <Plot xRange={[xMin, xMax]} yRange={[-0.5, 7.2]} width={620} height={360}>
        <Axes step={2} showGrid showTicks={false} />
        {/* 2pi asymptote guide */}
        <Polyline
          points={[
            [xMin, TWO_PI],
            [xMax, TWO_PI]
          ]}
          dash="4 5"
          opacity={OPACITY.faint}
        />
        {/* ghost: rest-frame kink (v = 0) */}
        <Polyline points={kinkRest} dash="5 4" opacity={OPACITY.faint} strokeWidth={1.4} />
        {/* primary: boosted kink */}
        <Polyline points={kinkNow} opacity={OPACITY.fg} strokeWidth={2.2} />
        <Dot x={0} y={Math.PI} r={3} opacity={OPACITY.accent} />
        {/* y-axis levels */}
        <Tex
          at={[xMin + 0.25, TWO_PI]}
          tex={String.raw`2\pi`}
          size={FONT_LABEL}
          opacity={OPACITY.dim}
        />
        <Tex
          at={[xMin + 0.25, Math.PI]}
          tex={String.raw`\pi`}
          size={FONT_LABEL}
          opacity={OPACITY.dim}
        />
        <Tex
          at={[xMin + 0.25, 0]}
          dy={14}
          tex={String.raw`0`}
          size={FONT_LABEL}
          opacity={OPACITY.dim}
        />
        <Tex at={[2.4, 5.7]} tex={String.raw`u(x)`} size={FONT_TEX} opacity={OPACITY.fg} />
        <Label at={[xMax - 0.3, 6.9]} anchor="end" size={FONT_SMALL} opacity={OPACITY.dim}>
          field
        </Label>
      </Plot>

      {/* GRADIENT panel: the soliton lump; area under it = 2pi always */}
      <Plot xRange={[xMin, xMax]} yRange={[-0.5, 7.2]} width={620} height={300}>
        <Axes step={2} showGrid showTicks={false} />
        {/* enclosed-area fill = conserved 2pi twist */}
        <Polyline points={gradArea} closed fillOpacity={0.09} strokeWidth={0} opacity={1} />
        {/* ghost: rest-frame gradient (v = 0, peak 2) */}
        <Polyline points={gradRest} dash="5 4" opacity={OPACITY.faint} strokeWidth={1.4} />
        {/* primary: boosted gradient lump */}
        <Polyline points={gradNow} opacity={OPACITY.fg} strokeWidth={2.2} />
        <Dot x={0} y={peak} r={3} opacity={OPACITY.accent} />
        {/* y-axis levels */}
        {[2, 4, 6].map(yk => (
          <Tex
            key={yk}
            at={[xMin + 0.25, yk]}
            tex={String(yk)}
            size={FONT_LABEL}
            opacity={OPACITY.dim}
          />
        ))}
        <Tex
          at={[xMin + 0.25, 0]}
          dy={14}
          tex={String.raw`0`}
          size={FONT_LABEL}
          opacity={OPACITY.dim}
        />
        <Tex
          at={[1.0, Math.min(peak, 6.2)]}
          dy={-4}
          tex={String.raw`u_x`}
          size={FONT_TEX}
          opacity={OPACITY.fg}
        />
        <Tex
          at={[0, 0.75]}
          anchor="middle"
          size={FONT_SMALL}
          opacity={OPACITY.dim}
          tex="\text{area} = 2\pi"
        />
        <Tex
          at={[xMax - 0.2, -0.5]}
          dy={6}
          anchor="end"
          tex={String.raw`x`}
          size={FONT_LABEL}
          opacity={OPACITY.dim}
        />
      </Plot>

      <Slider
        label="velocity v"
        value={v}
        min={0}
        max={0.95}
        step={0.05}
        onChange={setV}
        format={val => val.toFixed(2)}
      />

      {/* live readouts: Lorentz factor, width ratio, gradient peak, conserved twist */}
      <div
        style={{
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          gap: 28,
          flexWrap: 'wrap',
          marginTop: 14
        }}
      >
        <span style={{ ...readout, opacity: OPACITY.fg }}>
          <KatexInline tex={String.raw`\gamma=\tfrac{1}{\sqrt{1-v^2}}`} />
          <span style={num}>{gamma.toFixed(2)}</span>
        </span>
        <span style={{ ...readout, opacity: OPACITY.accent }}>
          <KatexInline tex={String.raw`\ell/\ell_0=\sqrt{1-v^2}`} />
          <span style={num}>{Math.sqrt(1 - v * v).toFixed(2)}</span>
        </span>
        <span style={{ ...readout, opacity: OPACITY.accent }}>
          <KatexInline tex={String.raw`\max u_x=2\gamma`} />
          <span style={num}>{peak.toFixed(2)}</span>
        </span>
        <span style={{ ...readout, opacity: OPACITY.dim }}>
          <KatexInline tex={String.raw`\int u_x\,dx=2\pi`} />
        </span>
      </div>
    </div>
  )
}

// 06.8.3 : SgPotentialVacua: coupled washboard potential + kink field.
// Left: V(u) = 1 - cos(u) rotated 90 deg so its minima at 0, 2 pi, 4 pi and barrier peak
// (V = 2 at u = pi) sit on a shared vertical u-axis. Right: the exact kink field
// u(x) = 4*arctan(e^x) climbing from the u = 0 vacuum to the adjacent u = 2 pi vacuum.
// Dashed guides tie the field asymptotes to the adjacent minima and mark u = pi (barrier
// top) reached at the kink midpoint x = 0. Both curves are sampled from closed forms.
export function SgPotentialVacua() {
  const TWO_PI = 2 * Math.PI
  const FOUR_PI = 4 * Math.PI
  // Vertical (u) axis spans the ladder of three vacua with headroom.
  const uMin = -1.0,
    uMax = FOUR_PI + 1.0
  // Horizontal layout in plot units. Potential occupies [hPotMax, hAxis]; field occupies
  // [hFieldL, hFieldR]; the gap between them is where the coupling guides cross.
  const hAxis = 7.0 // V = 0 reference (potential troughs sit here)
  const sV = 2.2 // V -> horizontal scale; barrier V=2 reaches hAxis - 4.4 = 2.6
  const hFieldL = 8.5,
    hFieldR = 21.0
  const xMin = -6.5,
    xMax = 6.5
  const sX = (hFieldR - hFieldL) / (xMax - xMin)
  const hX = x => hFieldL + (x - xMin) * sX // field x -> horizontal
  const hV = V => hAxis - sV * V // potential V -> horizontal (grows leftward)

  const nPot = 400
  const potPts = Array.from({ length: nPot }, (_, i) => {
    const u = uMin + (i / (nPot - 1)) * (uMax - uMin)
    return [hV(1 - Math.cos(u)), u]
  })
  const nField = 400
  const fieldPts = Array.from({ length: nField }, (_, i) => {
    const x = xMin + (i / (nField - 1)) * (xMax - xMin)
    return [hX(x), 4 * Math.atan(Math.exp(x))]
  })
  const vacua = [0, TWO_PI, FOUR_PI]

  return (
    <Plot xRange={[0, 23]} yRange={[uMin - 0.4, uMax + 0.4]} width={720} height={560}>
      {/* Tertiary: potential V=0 axis + field x-axis baseline */}
      <Polyline
        points={[
          [hAxis, uMin],
          [hAxis, uMax]
        ]}
        opacity={OPACITY.faint}
        strokeWidth={STROKE_SECONDARY}
      />
      <Polyline
        points={[
          [hFieldL, 0],
          [hFieldR, 0]
        ]}
        opacity={OPACITY.faint}
        strokeWidth={STROKE_SECONDARY}
      />

      {/* Secondary: coupling guides: adjacent vacua tied to the kink's asymptotes */}
      {[0, TWO_PI].map((u, i) => (
        <Polyline
          key={`g${i}`}
          points={[
            [hV(0), u],
            [hFieldR, u]
          ]}
          opacity={OPACITY.dim}
          strokeWidth={STROKE_SECONDARY}
          dash="5 4"
        />
      ))}
      {/* Barrier-top guide: V=2 peak at u=pi tied to the kink midpoint */}
      <Polyline
        points={[
          [hV(2), Math.PI],
          [hX(0), Math.PI]
        ]}
        opacity={OPACITY.faint}
        strokeWidth={STROKE_SECONDARY}
        dash="2 4"
      />

      {/* Primary: the two computed curves */}
      <Polyline points={potPts} opacity={OPACITY.fg} strokeWidth={2} />
      <Polyline points={fieldPts} opacity={OPACITY.fg} strokeWidth={2} />

      {/* Vacua minima */}
      {vacua.map((u, i) => (
        <Dot key={`v${i}`} x={hAxis} y={u} r={4} opacity={OPACITY.fg} />
      ))}
      {/* Barrier peak + kink midpoint */}
      <Dot x={hV(2)} y={Math.PI} r={3} opacity={OPACITY.accent} />
      <Dot x={hX(0)} y={Math.PI} r={3} opacity={OPACITY.accent} />

      {/* u-axis vacuum labels (far left) */}
      <Tex at={[2.2, 0]} tex={String.raw`0`} size={FONT_LABEL} opacity={OPACITY.dim} anchor="end" />
      <Tex
        at={[2.2, TWO_PI]}
        tex={String.raw`2\pi`}
        size={FONT_LABEL}
        opacity={OPACITY.dim}
        anchor="end"
      />
      <Tex
        at={[2.2, FOUR_PI]}
        tex={String.raw`4\pi`}
        size={FONT_LABEL}
        opacity={OPACITY.dim}
        anchor="end"
      />

      {/* Panel + feature labels */}
      <Tex
        at={[2.6, FOUR_PI + 0.9]}
        tex={String.raw`V(u)=1-\cos u`}
        size={FONT_LABEL}
        opacity={OPACITY.dim}
        anchor="start"
      />
      <Tex
        at={[14.0, FOUR_PI + 0.9]}
        tex={String.raw`u(x)=4\arctan e^{x}`}
        size={FONT_LABEL}
        opacity={OPACITY.dim}
        anchor="middle"
      />
    </Plot>
  )
}

// 06.8.4 : SgKinkAntikink: opposite topological charges, computed by winding.
// Left panel : exact static profiles phi(x): kink 0->2pi, antikink 2pi->0.
// Right panel: vacuum-manifold circle (phi lives on a circle since V=1-cos phi).
//   As the probe sweeps x from -inf to +inf the field winds the circle once:
//   kink CCW (Q=+1), antikink CW (Q=-1). The winding fraction reaches exactly
//   +-1 at the boundaries, so Q = (1/2pi)[phi(+inf)-phi(-inf)] is *computed*.
export function SgKinkAntikink() {
  const TAU = Math.PI * 2
  const [x0, setX0] = React.useState(0)

  // Exact sine-Gordon static one-soliton profiles.
  const phiK = x => 4 * Math.atan(Math.exp(x)) // kink: 0 -> 2pi
  const phiA = x => 4 * Math.atan(Math.exp(-x)) // antikink: 2pi -> 0  (= TAU - phiK)
  const pk = phiK(x0)
  const pa = phiA(x0)

  // left panel geometry: field profile phi(x)
  const L = { x0: 70, x1: 414, yTop: 50, yBot: 290 }
  const wxMin = -4.5,
    wxMax = 4.5
  const FX = wx => L.x0 + ((wx - wxMin) / (wxMax - wxMin)) * (L.x1 - L.x0)
  const FY = phi => L.yBot - (phi / TAU) * (L.yBot - L.yTop)
  const N = 180
  const xs = Array.from({ length: N }, (_, i) => wxMin + (i / (N - 1)) * (wxMax - wxMin))
  const toPath = fn => 'M' + xs.map(x => `${FX(x).toFixed(1)} ${FY(fn(x)).toFixed(1)}`).join(' L')

  // right panel geometry: vacuum-manifold circles
  const R = 48
  const kc = { cx: 585, cy: 90 } // kink circle
  const ac = { cx: 585, cy: 252 } // antikink circle
  const cpt = (c, th) => [c.cx + R * Math.cos(th), c.cy - R * Math.sin(th)]
  const arcPath = (c, th0, th1, steps = 96) => {
    const pts = []
    for (let i = 0; i <= steps; i++) {
      const th = th0 + ((th1 - th0) * i) / steps
      const [px, py] = cpt(c, th)
      pts.push(`${px.toFixed(1)} ${py.toFixed(1)}`)
    }
    return 'M' + pts.join(' L')
  }
  // arrowhead barbs at `tip`, pointing along unit travel direction `dir`
  const headPts = (tip, dir, s = 8) => {
    const [tx, ty] = tip
    const nx = -dir[1],
      ny = dir[0]
    const bx = tx - dir[0] * s,
      by = ty - dir[1] * s
    return (
      `${(bx + nx * s * 0.55).toFixed(1)},${(by + ny * s * 0.55).toFixed(1)} ` +
      `${tx.toFixed(1)},${ty.toFixed(1)} ` +
      `${(bx - nx * s * 0.55).toFixed(1)},${(by - ny * s * 0.55).toFixed(1)}`
    )
  }

  // kink: theta 0 -> pk (CCW). antikink: theta 2pi -> pa (CW).
  const kTip = cpt(kc, pk)
  const aTip = cpt(ac, pa)
  const kDir = [-Math.sin(pk), -Math.cos(pk)] // unit tangent, theta increasing (CCW)
  const aDir = [Math.sin(pa), Math.cos(pa)] // unit tangent, theta decreasing (CW)

  // winding accumulated from -inf up to the probe (turns of the circle)
  const wK = pk / TAU // 0 .. +1
  const wA = pa / TAU - 1 // 0 .. -1
  const sgn = v => (v >= 0 ? '+' : '−')
  const mag = v => Math.abs(v).toFixed(2)

  return (
    <div>
      <Canvas w={720} h={340}>
        <Label x={70} y={26} anchor="start" opacity={OPACITY.dim} size={FONT_LABEL}>
          Field profile
        </Label>
        <Label x={585} y={26} anchor="middle" opacity={OPACITY.dim} size={FONT_LABEL}>
          Vacuum circle
        </Label>

        {/* panel divider */}
        <line
          x1={452}
          y1={42}
          x2={452}
          y2={300}
          stroke={FG}
          strokeOpacity={OPACITY.hair}
          strokeWidth={STROKE_SECONDARY}
        />

        {/* ---- LEFT: field profile ---- */}
        <line
          x1={L.x0}
          y1={L.yTop}
          x2={L.x0}
          y2={L.yBot}
          stroke={FG}
          strokeOpacity={OPACITY.dim}
          strokeWidth={STROKE_SECONDARY}
        />
        {/* two vacua: dotted guide lines + value labels */}
        <line
          x1={L.x0}
          y1={FY(TAU)}
          x2={L.x1}
          y2={FY(TAU)}
          stroke={FG}
          strokeOpacity={OPACITY.faint}
          strokeWidth={STROKE_SECONDARY}
          strokeDasharray="2 4"
        />
        <line
          x1={L.x0}
          y1={FY(0)}
          x2={L.x1}
          y2={FY(0)}
          stroke={FG}
          strokeOpacity={OPACITY.faint}
          strokeWidth={STROKE_SECONDARY}
          strokeDasharray="2 4"
        />
        <TexPx
          x={62}
          y={FY(TAU)}
          tex={String.raw`2\pi`}
          size={FONT_LABEL}
          anchor="end"
          opacity={OPACITY.dim}
        />
        <TexPx
          x={62}
          y={FY(0)}
          tex={String.raw`0`}
          size={FONT_LABEL}
          anchor="end"
          opacity={OPACITY.dim}
        />
        <Label x={L.x1} y={FY(TAU) - 8} anchor="end" opacity={OPACITY.faint} size={FONT_TINY}>
          vacua
        </Label>

        {/* curves */}
        <path
          d={toPath(phiK)}
          fill="none"
          stroke={FG}
          strokeWidth={2}
          opacity={OPACITY.fg}
          strokeLinecap="round"
          strokeLinejoin="round"
        />
        <path
          d={toPath(phiA)}
          fill="none"
          stroke={FG}
          strokeWidth={2}
          opacity={OPACITY.dim}
          strokeDasharray="7 4"
          strokeLinecap="round"
          strokeLinejoin="round"
        />
        {/* curve identity labels at their high ends, no leader lines */}
        <TexPx
          x={FX(2.7)}
          y={FY(phiK(2.7)) - 4}
          tex={String.raw`\text{kink}`}
          size={FONT_LABEL}
          anchor="start"
          opacity={OPACITY.fg}
        />
        <TexPx
          x={FX(-4.4)}
          y={FY(phiA(-4.4)) - 4}
          tex={String.raw`\text{antikink}`}
          size={FONT_LABEL}
          anchor="start"
          opacity={OPACITY.dim}
        />

        {/* probe line + markers */}
        <line
          x1={FX(x0)}
          y1={L.yTop - 4}
          x2={FX(x0)}
          y2={L.yBot + 4}
          stroke={FG}
          strokeOpacity={OPACITY.dim}
          strokeWidth={STROKE_SECONDARY}
          strokeDasharray="3 3"
        />
        <circle cx={FX(x0)} cy={FY(pk)} r={3.5} fill={FG} opacity={OPACITY.fg} />
        <circle
          cx={FX(x0)}
          cy={FY(pa)}
          r={3.5}
          fill="var(--bg)"
          stroke={FG}
          strokeWidth={1.4}
          opacity={OPACITY.fg}
        />
        <Label
          x={FX(x0)}
          y={L.yBot + 22}
          anchor="middle"
          opacity={OPACITY.dim}
          size={FONT_SMALL}
          upper={false}
        >
          {`x = ${x0.toFixed(1)}`}
        </Label>

        {/* ---- RIGHT: vacuum-manifold circles ---- */}
        {[
          { c: kc, label: 'Q = +1', wind: wK, tip: kTip, dir: kDir, dash: null, op: OPACITY.fg },
          { c: ac, label: 'Q = -1', wind: wA, tip: aTip, dir: aDir, dash: '6 4', op: OPACITY.dim }
        ].map((s, i) => (
          <g key={i}>
            {/* base circle (the vacuum manifold) */}
            <circle
              cx={s.c.cx}
              cy={s.c.cy}
              r={R}
              fill="none"
              stroke={FG}
              strokeOpacity={OPACITY.faint}
              strokeWidth={STROKE_SECONDARY}
            />
            {/* identified vacuum point 0 = 2pi at theta = 0 */}
            <circle
              cx={s.c.cx + R}
              cy={s.c.cy}
              r={3}
              fill="var(--bg)"
              stroke={FG}
              strokeWidth={STROKE_SECONDARY}
              opacity={OPACITY.dim}
            />
            <TexPx
              x={s.c.cx + R + 7}
              y={s.c.cy}
              tex={String.raw`0\equiv 2\pi`}
              size={FONT_SMALL}
              anchor="start"
              opacity={OPACITY.dim}
            />
            {/* traced winding arc */}
            <path
              d={i === 0 ? arcPath(s.c, 0, pk) : arcPath(s.c, TAU, pa)}
              fill="none"
              stroke={FG}
              strokeWidth={2}
              opacity={s.op}
              strokeDasharray={s.dash || undefined}
              strokeLinecap="round"
            />
            {/* direction arrowhead at the moving end */}
            <polyline
              points={headPts(s.tip, s.dir)}
              fill="none"
              stroke={FG}
              strokeWidth={2}
              opacity={s.op}
              strokeLinecap="round"
              strokeLinejoin="round"
            />
            {/* moving field point on the circle */}
            <circle
              cx={s.tip[0]}
              cy={s.tip[1]}
              r={4}
              fill={i === 0 ? FG : 'var(--bg)'}
              stroke={FG}
              strokeWidth={1.4}
              opacity={OPACITY.fg}
            />
            {/* charge at the centre */}
            <TexPx
              x={s.c.cx}
              y={s.c.cy + 5}
              tex={String.raw`${s.label}`}
              size={FONT_TEX}
              anchor="middle"
              opacity={OPACITY.fg}
            />
            {/* live winding accumulated to the probe */}
            <Label
              x={s.c.cx}
              y={s.c.cy + R + 17}
              anchor="middle"
              opacity={OPACITY.dim}
              size={FONT_SMALL}
            >
              {`${sgn(s.wind)}${mag(s.wind)} turn`}
            </Label>
          </g>
        ))}
      </Canvas>

      <Slider
        label="probe x"
        value={x0}
        min={-4.5}
        max={4.5}
        step={0.1}
        onChange={setX0}
        format={v => v.toFixed(1)}
      />
    </div>
  )
}

// 06.8.5 : SgBreather: animated breather solution
// u(x,t) = 4*arctan( (sqrt(1-omega^2)/omega)*sin(omega*t) / cosh(sqrt(1-omega^2)*x) )
// omega slider in (0.05, 0.95). Animated via useAnimationTime.
export function SgBreather() {
  const [omega, setOmega] = React.useState(0.5)
  const [playing, setPlaying] = React.useState(true)
  const t = useAnimationTime(playing, 1.0)
  const sqrtTerm = Math.sqrt(Math.max(1 - omega * omega, 1e-6))
  const period = (2 * Math.PI) / omega
  const nPts = 400
  const xMin = -10,
    xMax = 10
  const xs = Array.from({ length: nPts }, (_, i) => xMin + (i / (nPts - 1)) * (xMax - xMin))
  const breatherPts = xs.map(x => {
    const val = 4 * Math.atan((sqrtTerm / omega) * (Math.sin(omega * t) / Math.cosh(sqrtTerm * x)))
    return [x, val]
  })
  // amplitude envelope: the breather swings between +-4*atan((sqrt(1-w^2)/w)/cosh(...))
  const envTop = xs.map(x => [x, 4 * Math.atan(sqrtTerm / omega / Math.cosh(sqrtTerm * x))])
  const envBot = envTop.map(([x, y]) => [x, -y])
  return (
    <div>
      <Plot xRange={[xMin, xMax]} yRange={[-7, 7]} width={620} height={400}>
        <Axes step={2} showGrid={true} showTicks={true} />
        {/* envelope (max swing over a period) */}
        <Polyline points={envTop} dash="4 4" opacity={OPACITY.faint} strokeWidth={1.4} />
        <Polyline points={envBot} dash="4 4" opacity={OPACITY.faint} strokeWidth={1.4} />
        {/* instantaneous field */}
        <Polyline points={breatherPts} opacity={OPACITY.fg} strokeWidth={2} />
        <Tex
          at={[-9.5, 6.2]}
          tex={String.raw`u(x,t)`}
          size={FONT_LABEL}
          opacity={OPACITY.fg}
          anchor="start"
        />
        <Tex
          at={[9.5, 4.7]}
          tex={String.raw`\text{envelope}`}
          size={FONT_SMALL}
          opacity={OPACITY.faint}
          anchor="end"
        />
      </Plot>

      {/* Readout row: breather frequency and period (valid for 0 < ω < 1) */}
      <div
        style={{
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          gap: 28,
          flexWrap: 'wrap',
          marginTop: 12
        }}
      >
        <span
          style={{
            display: 'inline-flex',
            alignItems: 'center',
            gap: 8,
            fontSize: FONT_TEX,
            opacity: OPACITY.fg
          }}
        >
          <KatexInline tex={String.raw`\omega`} />
          <span style={{ fontVariantNumeric: 'tabular-nums', fontSize: FONT_CONTROL }}>
            {omega.toFixed(2)}
          </span>
        </span>
        <span
          style={{
            display: 'inline-flex',
            alignItems: 'center',
            gap: 8,
            fontSize: FONT_TEX,
            opacity: OPACITY.dim
          }}
        >
          <KatexInline tex={String.raw`T=2\pi/\omega`} />
          <span style={{ fontVariantNumeric: 'tabular-nums', fontSize: FONT_CONTROL }}>
            {period.toFixed(1)}
          </span>
        </span>
        <span
          style={{
            display: 'inline-flex',
            alignItems: 'center',
            gap: 8,
            fontSize: FONT_TEX,
            opacity: OPACITY.dim
          }}
        >
          <KatexInline tex={String.raw`0<\omega<1`} />
        </span>
      </div>
      <PlayPause playing={playing} onToggle={() => setPlaying(p => !p)} />
      <Slider
        label="frequency ω"
        value={omega}
        min={0.05}
        max={0.95}
        step={0.05}
        onChange={setOmega}
        format={v => v.toFixed(2)}
      />
    </div>
  )
}

// 06.8.6 : SgCnoidalWave: Jacobi-elliptic cnoidal solution of SG.
// Top band  : the genuine Jacobi cn(x; m) generator, via the descending Landen / AGM
//             transformation (Abramowitz & Stegun 16.4): exact for all m in [0,1).
//             Plotted at a FIXED spatial scale (x is the cn argument, no period
//             renormalization) so the wavelength lambda = 4K(m) truly diverges as m -> 1.
// Bottom band: the sine-Gordon field y = 4*arctan(A*cn) the hero equation builds from cn.
//             m -> 0: cn = cos, small ripple. m -> 1: cn -> sech, sharp alternating
//             pulses on a flat background = one soliton per fundamental domain.
export function SgCnoidalWave() {
  const [m, setM] = React.useState(0.5)
  // Complete elliptic integral K(m) via AGM.
  function ellipticK(mm) {
    if (mm >= 1) return Infinity
    let a = 1,
      b = Math.sqrt(1 - mm),
      c
    for (let i = 0; i < 14; i++) {
      c = (a + b) / 2
      b = Math.sqrt(a * b)
      a = c
    }
    return Math.PI / (2 * a)
  }
  // Jacobi amplitude am(u; m) via AGM. m = k^2 in [0,1). A&S 16.4. sn = sin(am).
  function am(u, mm) {
    if (mm <= 1e-9) return u
    if (mm >= 1 - 1e-9) return Math.asin(Math.tanh(u)) // gd(u): sn -> tanh
    const CA = 1e-10
    const aArr = [1]
    const cArr = [Math.sqrt(mm)] // c0 = k
    let bPrev = Math.sqrt(1 - mm) // b0 = k'
    let n = 0
    while (Math.abs(cArr[n]) > CA && n < 25) {
      const aNext = 0.5 * (aArr[n] + bPrev)
      const cNext = 0.5 * (aArr[n] - bPrev)
      const bNext = Math.sqrt(aArr[n] * bPrev)
      n++
      aArr[n] = aNext
      cArr[n] = cNext
      bPrev = bNext
    }
    let phi = aArr[n] * u * Math.pow(2, n)
    for (let k = n; k >= 1; k--) {
      phi = 0.5 * (phi + Math.asin((cArr[k] / aArr[k]) * Math.sin(phi)))
    }
    return phi
  }
  const sn = (u, mm) => Math.sin(am(u, mm))

  const K = ellipticK(m)
  const lambda = 4 * K // sn period in argument units (diverges as m -> 1)
  const nPts = 700
  const xMin = -15,
    xMax = 15
  const xs = Array.from({ length: nPts }, (_, i) => xMin + (i / (nPts - 1)) * (xMax - xMin))

  // Stacked bands, shared x-mapping so field swings sit directly under sn = +-1.
  const SN_BASE = 2.3,
    SN_AMP = 1.35
  const SG_BASE = -2.3,
    SG_SCALE = 0.45 // maps u in [0, 2pi] (centred on pi) into the lower band
  const rootM = Math.sqrt(m)
  const snPts = xs.map(x => [x, SN_BASE + SN_AMP * sn(x, m)])
  // Exact static SG cnoidal wave: u = pi + 2 arcsin(sqrt(m) sn(x|m)) solves u_xx = sin u.
  const sgPts = xs.map(x => [x, SG_BASE + SG_SCALE * 2 * Math.asin(rootM * sn(x, m))])
  const vacTop = SG_BASE + SG_SCALE * Math.PI // u = 2pi level
  const vacBot = SG_BASE - SG_SCALE * Math.PI // u = 0 level

  const regime =
    m > 0.96
      ? String.raw`\text{kink--antikink lattice}`
      : m < 0.08
        ? String.raw`\text{small ripple about }u=\pi`
        : String.raw`\text{cnoidal regime}`

  return (
    <div>
      <Plot xRange={[xMin, xMax]} yRange={[-4.2, 4.2]} width={620} height={440}>
        {/* band baselines (tertiary): sn = 0 above, u = pi below */}
        <Polyline
          points={[
            [xMin, SN_BASE],
            [xMax, SN_BASE]
          ]}
          opacity={OPACITY.faint}
          strokeWidth={STROKE_SECONDARY}
          dash="2 5"
        />
        <Polyline
          points={[
            [xMin, SG_BASE],
            [xMax, SG_BASE]
          ]}
          opacity={OPACITY.faint}
          strokeWidth={STROKE_SECONDARY}
          dash="2 5"
        />
        {/* vacuum guides: the u = 0 and u = 2pi levels the lattice reaches as m -> 1 */}
        <Polyline
          points={[
            [xMin, vacTop],
            [xMax, vacTop]
          ]}
          opacity={OPACITY.hair}
          strokeWidth={STROKE_GUIDE}
          dash="5 5"
        />
        <Polyline
          points={[
            [xMin, vacBot],
            [xMax, vacBot]
          ]}
          opacity={OPACITY.hair}
          strokeWidth={STROKE_GUIDE}
          dash="5 5"
        />
        <Tex
          at={[xMax - 0.4, vacTop]}
          dy={-7}
          tex={String.raw`u=2\pi`}
          size={FONT_TINY}
          opacity={OPACITY.faint}
          anchor="end"
        />
        <Tex
          at={[xMax - 0.4, vacBot]}
          dy={12}
          tex={String.raw`u=0`}
          size={FONT_TINY}
          opacity={OPACITY.faint}
          anchor="end"
        />
        {/* secondary: the exact static SG cnoidal wave built on sn */}
        <Polyline points={sgPts} opacity={OPACITY.accent} strokeWidth={1.6} />
        {/* primary: the Jacobi sn generator */}
        <Polyline points={snPts} opacity={OPACITY.fg} strokeWidth={2.2} />
        {/* band labels (left) */}
        <Tex
          at={[xMin + 0.5, 3.95]}
          tex={String.raw`\mathrm{sn}(x\,;\,m)`}
          size={FONT_TEX}
          opacity={OPACITY.dim}
          anchor="start"
        />
        <Tex
          at={[xMin + 0.5, -0.55]}
          tex={String.raw`u=\pi+2\arcsin\!\bigl(\sqrt{m}\,\mathrm{sn}\bigr)`}
          size={FONT_TEX}
          opacity={OPACITY.dim}
          anchor="start"
        />
        <Tex
          at={[xMax - 0.5, 0.2]}
          tex={String.raw`u_{xx}=\sin u\ \text{exactly}`}
          size={FONT_SMALL}
          opacity={OPACITY.faint}
          anchor="end"
        />
        <Tex
          at={[xMax - 0.5, 2.85]}
          tex={regime}
          size={FONT_LABEL}
          opacity={OPACITY.faint}
          anchor="end"
        />
      </Plot>

      {/* Readout row: the diverging wavelength */}
      <div
        style={{
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          gap: 28,
          flexWrap: 'wrap',
          marginTop: 12
        }}
      >
        <span
          style={{
            display: 'inline-flex',
            alignItems: 'center',
            gap: 8,
            fontSize: FONT_TEX,
            opacity: OPACITY.fg
          }}
        >
          <KatexInline tex={String.raw`\lambda=4K(m)`} />
          <span style={{ fontVariantNumeric: 'tabular-nums', fontSize: FONT_CONTROL }}>
            {Number.isFinite(lambda) ? lambda.toFixed(1) : '∞'}
          </span>
        </span>
      </div>
      <Slider
        label="modulus m"
        value={m}
        min={0.01}
        max={0.999}
        step={0.001}
        onChange={setM}
        format={v => v.toFixed(3)}
      />
    </div>
  )
}

// MODULE NS · VISCOUS FLUIDS & NAVIER-STOKES

// NS.1: Couette Flow: linear velocity profile u(y) = U·y/h between sliding plates
export function NsCouetteFlow() {
  const [U, setU] = React.useState(1.0)
  const [playing, setPlaying] = React.useState(true)
  const t = useAnimationTime(playing, 1)
  const h = 4.0
  const eta = 1.0
  const tau = (eta * U) / h // shear stress is uniform across the gap
  const pts = []
  for (let i = 0; i <= 40; i++) {
    const y = (i / 40) * h
    pts.push([U * (y / h), y])
  }
  // Advecting dye lines: a vertical line of dye injected across the gap shears into a
  // straight diagonal because u is linear in y. Straight stays straight, only tilted -
  // the signature of simple shear. Three staggered lines keep one mid-shear at all times.
  const nLines = 3
  const period = 3.2
  const travel = 1.3
  const dyeLines = []
  for (let j = 0; j < nLines; j++) {
    const phase = (((t / period + j / nLines) % 1) + 1) % 1
    const alpha = Math.sin(Math.PI * phase) // fade in at injection, out at exit
    const linePts = []
    for (let i = 0; i <= 20; i++) {
      const y = (i / 20) * h
      linePts.push([U * (y / h) * phase * travel, y])
    }
    dyeLines.push({ linePts, alpha })
  }
  return (
    <div>
      <Plot xRange={[-0.3, 2.5]} yRange={[-0.3, 4.8]} width={620} height={440}>
        <Axes step={1} showGrid={true} showTicks={true} />
        {/* advecting dye lines (drawn under the profile) */}
        {dyeLines.map((d, j) => (
          <React.Fragment key={j}>
            <Polyline
              points={d.linePts}
              opacity={OPACITY.dim * d.alpha}
              strokeWidth={STROKE_PRIMARY}
            />
            <Dot
              x={d.linePts[d.linePts.length - 1][0]}
              y={h}
              r={2.5}
              opacity={OPACITY.fg * d.alpha}
            />
          </React.Fragment>
        ))}
        {/* velocity profile */}
        <Polyline points={pts} opacity={OPACITY.fg} strokeWidth={2} />
        {/* stationary bottom plate */}
        <Polyline
          points={[
            [-0.3, 0],
            [2.5, 0]
          ]}
          opacity={OPACITY.accent}
          strokeWidth={2}
        />
        {/* moving top plate */}
        <Polyline
          points={[
            [-0.3, h],
            [2.5, h]
          ]}
          opacity={OPACITY.accent}
          strokeWidth={2}
        />
        {/* velocity arrows at sample heights */}
        {[0.5, 1.0, 1.5, 2.0, 2.5, 3.0, 3.5].map(y => {
          const u = U * (y / h)
          return u > 0.02 ? (
            <Arrow
              key={y}
              from={[0, y]}
              to={[u, y]}
              opacity={OPACITY.faint}
              strokeWidth={STROKE_SECONDARY}
            />
          ) : null
        })}
        {/* labels */}
        <Tex
          at={[-0.2, 4.4]}
          tex={String.raw`\text{moving plate } U`}
          size={FONT_SMALL}
          opacity={OPACITY.dim}
          anchor="start"
        />
        <Tex
          at={[-0.2, -0.2]}
          tex={String.raw`\text{fixed plate}`}
          size={FONT_SMALL}
          opacity={OPACITY.dim}
          anchor="start"
        />
        <Tex
          at={[U + 0.05, h / 2]}
          tex={String.raw`u(y)=U\tfrac{y}{h}`}
          size={FONT_LABEL}
          opacity={OPACITY.fg}
          anchor="start"
        />
        <Tex
          at={[2.3, 0.3]}
          tex={String.raw`x`}
          size={FONT_LABEL}
          opacity={OPACITY.dim}
          anchor="start"
        />
        <Tex
          at={[0.05, 4.6]}
          tex={String.raw`y`}
          size={FONT_LABEL}
          opacity={OPACITY.dim}
          anchor="start"
        />
      </Plot>

      {/* Readout row: the uniform shear stress across the gap */}
      <div
        style={{
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          gap: 28,
          flexWrap: 'wrap',
          marginTop: 12
        }}
      >
        <span
          style={{
            display: 'inline-flex',
            alignItems: 'center',
            gap: 8,
            fontSize: FONT_TEX,
            opacity: OPACITY.accent
          }}
        >
          <KatexInline tex={String.raw`\tau=\eta\,U/h\ \text{(uniform)}`} />
          <span style={{ fontVariantNumeric: 'tabular-nums', fontSize: FONT_CONTROL }}>
            {tau.toFixed(2)}
          </span>
        </span>
      </div>
      <div style={{ display: 'flex', gap: 16, alignItems: 'center', flexWrap: 'wrap' }}>
        <PlayPause playing={playing} onToggle={() => setPlaying(p => !p)} onReset={() => {}} />
        <div style={{ flex: 1, minWidth: 220 }}>
          <Slider
            label="plate speed U"
            value={U}
            min={0.1}
            max={1.5}
            step={0.05}
            onChange={setU}
            format={v => v.toFixed(2)}
          />
        </div>
      </div>
    </div>
  )
}

// NS.2: Poiseuille Flow: parabolic velocity profile in a pipe (blood-in-artery framing)
export function NsPoiseuilleFlow() {
  const [dPdz, setDPdz] = React.useState(1.0)
  const [playing, setPlaying] = React.useState(true)
  const t = useAnimationTime(playing, 1)
  const a = 3.0
  const eta = 1.0
  // v(r) = ((-dP/dz)/4η)(a² - r²): dPdz slider is the magnitude of the driving gradient
  const vMax = (dPdz * a * a) / (4 * eta)
  const vMean = vMax / 2 // cross-sectional average for a circular pipe
  const Q = (Math.PI * Math.pow(a, 4) * dPdz) / (8 * eta) // Hagen–Poiseuille
  const xMax = vMax + 0.9 // dynamic so the nose never overflows the frame
  const nPts = 60
  const profilePts = []
  for (let i = 0; i <= nPts; i++) {
    const r = -a + (2 * a * i) / nPts
    const v = (dPdz * (a * a - r * r)) / (4 * eta)
    profilePts.push([v, r])
  }
  // Advecting dye rakes: a vertical dye line deforms into a parabolic bullet nose because
  // v(r) is parabolic. Each particle moves at its true local speed v(r). Three staggered
  // rakes keep one mid-stream at all times.
  const nLines = 3
  const period = 3.4
  const rakes = []
  for (let j = 0; j < nLines; j++) {
    const phase = (((t / period + j / nLines) % 1) + 1) % 1
    const alpha = Math.sin(Math.PI * phase)
    const linePts = []
    for (let i = 0; i <= 40; i++) {
      const r = -a + (2 * a * i) / 40
      const v = (dPdz * (a * a - r * r)) / (4 * eta)
      linePts.push([v * phase, r])
    }
    rakes.push({ linePts, alpha })
  }
  return (
    <div>
      <Plot xRange={[-0.4, xMax]} yRange={[-3.6, 3.6]} width={620} height={440}>
        <Axes step={1} showGrid={true} showTicks={true} />
        {/* pipe walls */}
        <Polyline
          points={[
            [-0.4, a],
            [xMax, a]
          ]}
          opacity={OPACITY.accent}
          strokeWidth={2}
        />
        <Polyline
          points={[
            [-0.4, -a],
            [xMax, -a]
          ]}
          opacity={OPACITY.accent}
          strokeWidth={2}
        />
        {/* advecting dye rakes (drawn under the profile) */}
        {rakes.map((d, j) => (
          <React.Fragment key={j}>
            <Polyline
              points={d.linePts}
              opacity={OPACITY.dim * d.alpha}
              strokeWidth={STROKE_PRIMARY}
            />
            <Dot x={d.linePts[20][0]} y={0} r={2.5} opacity={OPACITY.fg * d.alpha} />
          </React.Fragment>
        ))}
        {/* velocity profile */}
        <Polyline points={profilePts} opacity={OPACITY.fg} strokeWidth={2} />
        {/* centerline */}
        <Polyline
          points={[
            [0, -a],
            [0, a]
          ]}
          opacity={OPACITY.faint}
          dash="4 4"
          strokeWidth={STROKE_SECONDARY}
        />
        {/* mean-velocity reference: plug at v_max/2 */}
        <Polyline
          points={[
            [vMean, -a],
            [vMean, a]
          ]}
          opacity={OPACITY.faint}
          dash="2 3"
          strokeWidth={STROKE_SECONDARY}
        />
        {/* sample velocity arrows */}
        {[-2.4, -1.6, -0.8, 0, 0.8, 1.6, 2.4].map(r => {
          const v = (dPdz * (a * a - r * r)) / (4 * eta)
          return v > 0.05 ? (
            <Arrow
              key={r}
              from={[0, r]}
              to={[v, r]}
              opacity={OPACITY.faint}
              strokeWidth={STROKE_SECONDARY}
            />
          ) : null
        })}
        <Tex
          at={[vMax + 0.08, 0.2]}
          tex={String.raw`v_{\max}`}
          size={FONT_LABEL}
          opacity={OPACITY.fg}
          anchor="start"
        />
        <Tex
          at={[vMean + 0.05, a - 0.4]}
          tex={String.raw`\bar v=\tfrac{1}{2}v_{\max}`}
          size={FONT_SMALL}
          opacity={OPACITY.dim}
          anchor="start"
        />
        <Tex
          at={[0.05, 3.2]}
          tex={String.raw`a`}
          size={FONT_LABEL}
          opacity={OPACITY.dim}
          anchor="start"
        />
        <Tex
          at={[0.05, -3.45]}
          tex={String.raw`-a`}
          size={FONT_LABEL}
          opacity={OPACITY.dim}
          anchor="start"
        />
        <Tex
          at={[0.5, -3.2]}
          tex={String.raw`v(r)=\tfrac{(-dP/dz)}{4\eta}(a^2-r^2)`}
          size={FONT_SMALL}
          opacity={OPACITY.dim}
          anchor="start"
        />
        <Tex
          at={[0.05, 3.45]}
          tex={String.raw`\text{pipe wall}`}
          size={FONT_TINY}
          opacity={OPACITY.dim}
          anchor="start"
        />
        <Tex
          at={[xMax - 0.1, -3.2]}
          tex={String.raw`Q\propto a^4`}
          size={FONT_SMALL}
          opacity={OPACITY.accent}
          anchor="end"
        />
      </Plot>

      {/* Readout row: Hagen–Poiseuille throughput for this gradient */}
      <div
        style={{
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          gap: 28,
          flexWrap: 'wrap',
          marginTop: 12
        }}
      >
        <span
          style={{
            display: 'inline-flex',
            alignItems: 'center',
            gap: 8,
            fontSize: FONT_TEX,
            opacity: OPACITY.accent
          }}
        >
          <KatexInline tex={String.raw`Q=\dfrac{\pi a^4}{8\eta}\Bigl(-\dfrac{dP}{dz}\Bigr)`} />
          <span style={{ fontVariantNumeric: 'tabular-nums', fontSize: FONT_CONTROL }}>
            {Q.toFixed(1)}
          </span>
        </span>
        <span
          style={{
            display: 'inline-flex',
            alignItems: 'center',
            gap: 8,
            fontSize: FONT_TEX,
            opacity: OPACITY.dim
          }}
        >
          <KatexInline tex={String.raw`v_{\max}`} />
          <span style={{ fontVariantNumeric: 'tabular-nums', fontSize: FONT_CONTROL }}>
            {vMax.toFixed(2)}
          </span>
        </span>
      </div>
      <div style={{ display: 'flex', gap: 16, alignItems: 'center', flexWrap: 'wrap' }}>
        <PlayPause playing={playing} onToggle={() => setPlaying(p => !p)} onReset={() => {}} />
        <div style={{ flex: 1, minWidth: 220 }}>
          <Slider
            label="pressure gradient"
            value={dPdz}
            min={0.1}
            max={2.0}
            step={0.1}
            onChange={setDPdz}
            format={v => v.toFixed(1)}
          />
        </div>
      </div>
    </div>
  )
}

// NS.3: Strain-Rate Decomposition: expansion θ, shear σ, rotation r (static, 3-panel)
export function NsStrainRateDecomp() {
  const [playing, setPlaying] = React.useState(true)
  const t = useAnimationTime(playing, 1)
  const W = 620
  const H = 282
  const panW = W / 3
  const sq = 30 // half-side of the reference square in px
  const cx = [panW * 0.5, panW * 1.5, panW * 2.5]
  const cy = H / 2 - 8
  const period = 4.0
  const phase = (t / period) % 1
  const A = 0.5 - 0.5 * Math.cos(2 * Math.PI * phase) // smooth 0 → 1 → 0, fully reversible

  // each term of L = ⅓θI + σ + ω isolated as a deformation of a material square
  const sExp = 1 + 0.5 * A // isotropic expansion (area changes)
  const g = 0.5 * A // symmetric trace-free strain: stretch one diagonal, squash the other
  const phi = (A * 26 * Math.PI) / 180 // rigid rotation angle (area + shape preserved)
  const cosP = Math.cos(phi)
  const sinP = Math.sin(phi)
  const deform = [
    ([x, y]) => [sExp * x, sExp * y],
    ([x, y]) => [x + g * y, y + g * x],
    ([x, y]) => [x * cosP - y * sinP, x * sinP + y * cosP]
  ]

  // material-point grid carried by each deformation
  const grid = []
  for (let i = -2; i <= 2; i++)
    for (let j = -2; j <= 2; j++) grid.push([(i / 2) * sq, (j / 2) * sq])
  const corners = [
    [-sq, -sq],
    [sq, -sq],
    [sq, sq],
    [-sq, sq]
  ]
  const panels = [
    { i: 0, title: 'Expansion θ', sub: 'isotropic · area grows' },
    { i: 1, title: 'Shear σ', sub: 'symmetric · trace-free' },
    { i: 2, title: 'Rotation ω', sub: 'antisymmetric · no stress' }
  ]

  return (
    <div>
      <svg
        viewBox={`0 0 ${W} ${H}`}
        width="100%"
        style={{
          display: 'block',
          color: 'var(--text-primary)'
        }}
      >
        {/* dividers */}
        {[panW, panW * 2].map(x => (
          <line
            key={x}
            x1={x}
            y1={26}
            x2={x}
            y2={H - 44}
            stroke={FG}
            strokeOpacity={OPACITY.faint}
            strokeWidth={STROKE_SECONDARY}
          />
        ))}
        {panels.map(({ i, title, sub }) => {
          const f = deform[i]
          const cpts = corners
            .map(c => f(c))
            .map(([x, y]) => `${(cx[i] + x).toFixed(1)},${(cy + y).toFixed(1)}`)
            .join(' ')
          return (
            <g key={i}>
              {/* reference square */}
              <rect
                x={cx[i] - sq}
                y={cy - sq}
                width={sq * 2}
                height={sq * 2}
                fill="none"
                stroke={FG}
                strokeOpacity={OPACITY.faint}
                strokeWidth={STROKE_SECONDARY}
                strokeDasharray="3 3"
              />
              {/* deformed outline */}
              <polygon
                points={cpts}
                fill={FG}
                fillOpacity={0.04}
                stroke={FG}
                strokeOpacity={OPACITY.accent}
                strokeWidth={STROKE_PRIMARY}
              />
              {/* material points carried by the flow */}
              {grid.map((p, k) => {
                const [dx, dy] = f(p)
                return (
                  <circle
                    key={k}
                    cx={cx[i] + dx}
                    cy={cy + dy}
                    r={1.6}
                    fill={FG}
                    fillOpacity={OPACITY.dim}
                  />
                )
              })}
              {/* rotation arc */}
              {i === 2 && phi > 0.01 && (
                <path
                  d={`M ${cx[i] + sq} ${cy} A ${sq} ${sq} 0 0 1 ${(cx[i] + sq * cosP).toFixed(1)} ${(cy + sq * sinP).toFixed(1)}`}
                  fill="none"
                  stroke={FG}
                  strokeOpacity={OPACITY.dim}
                  strokeWidth={STROKE_SECONDARY}
                  strokeDasharray="3 2"
                />
              )}
              <text
                x={cx[i]}
                y={H - 26}
                textAnchor="middle"
                fill={FG}
                fillOpacity={OPACITY.fg}
                fontSize={FONT_LABEL}
                letterSpacing={LS_TIGHT}
                style={{ textTransform: 'uppercase' }}
              >
                {title}
              </text>
              <text
                x={cx[i]}
                y={H - 12}
                textAnchor="middle"
                fill={FG}
                fillOpacity={OPACITY.dim}
                fontSize={FONT_TINY}
              >
                {sub}
              </text>
            </g>
          )
        })}
        {/* top label */}
        <TexPx
          x={W / 2}
          y={16}
          anchor="middle"
          tex={
            '\\nabla v = \\tfrac{1}{3}\\theta I + \\sigma + \\omega\\ (\\text{expansion + shear + rotation})'
          }
          size={FONT_SMALL}
          width={528}
        />
      </svg>
      <div style={{ marginTop: 8 }}>
        <PlayPause playing={playing} onToggle={() => setPlaying(p => !p)} onReset={() => {}} />
      </div>
    </div>
  )
}

// NS.4: Reynolds Regime Map: schematic C_D vs Re_d log-log for flow past a cylinder
export function NsReynoldsRegimes() {
  const [logRe, setLogRe] = React.useState(3.0)
  // Computed creeping branch. A cylinder has NO 24/Re Stokes law (Stokes' paradox in 2D);
  // the accepted closed form is Lamb–Oseen: C_D ≈ 8π / [Re (2.002 − ln Re)], valid Re ≲ 1.
  const lamb = []
  for (let i = 0; i <= 24; i++) {
    const x = -1.3 + (i / 24) * 1.3 // log10 Re from −1.3 to 0
    const Re = Math.pow(10, x)
    const CD = (8 * Math.PI) / (Re * (2.002 - Math.log(Re)))
    lamb.push([x, Math.log10(CD)])
  }
  const lambEnd = lamb[lamb.length - 1][1]
  // Empirical regime map for a smooth cylinder (Re ≳ 1): measured data, schematic between points
  const empirical = [
    [0.0, lambEnd], // continuous with the computed branch at Re = 1
    [0.5, Math.log10(4.5)],
    [1.0, Math.log10(2.8)],
    [1.672, Math.log10(1.5)], // Re ≈ 47: Kármán vortex shedding begins
    [2.0, Math.log10(1.4)],
    [3.0, Math.log10(1.0)],
    [4.0, Math.log10(1.1)],
    [5.0, Math.log10(1.2)],
    [5.3, Math.log10(1.2)], // Re ≈ 2×10⁵: drag-crisis onset
    [5.5, Math.log10(0.5)],
    [5.7, Math.log10(0.3)], // crisis minimum
    [6.0, Math.log10(0.45)]
  ]
  const curve = lamb.concat(empirical)
  // interpolate log10 C_D at the slider's Re for the readout marker
  const evalY = lr => {
    for (let k = 1; k < curve.length; k++) {
      if (curve[k][0] >= lr) {
        const a = curve[k - 1]
        const b = curve[k]
        const f = (lr - a[0]) / (b[0] - a[0] || 1)
        return a[1] + f * (b[1] - a[1])
      }
    }
    return curve[curve.length - 1][1]
  }
  const markY = evalY(logRe)
  const markCD = Math.pow(10, markY)
  const markRe = Math.pow(10, logRe)
  const fmtRe =
    markRe < 100
      ? markRe.toFixed(markRe < 10 ? 2 : 0)
      : markRe.toExponential(1).replace('e+', '×10^')
  // KaTeX-friendly Re for the readout row
  const reTex =
    markRe < 100
      ? markRe.toFixed(markRe < 10 ? 2 : 0)
      : (() => {
          const e = Math.floor(logRe)
          const mant = Math.pow(10, logRe - e)
          return `${mant.toFixed(1)}\\times10^{${e}}`
        })()
  return (
    <div>
      <Plot xRange={[-1.7, 6.7]} yRange={[-1.0, 2.3]} width={620} height={440}>
        <Axes step={1} showGrid={true} showTicks={false} showOrigin={false} />
        {/* regime boundaries */}
        {[
          [1.672, '47'],
          [5.3, '2\\times10^5']
        ].map(([x]) => (
          <Polyline
            key={x}
            points={[
              [x, -1.0],
              [x, 2.3]
            ]}
            opacity={OPACITY.faint}
            dash="3 4"
            strokeWidth={STROKE_SECONDARY}
          />
        ))}
        {/* computed Lamb–Oseen branch */}
        <Polyline points={lamb} opacity={OPACITY.fg} strokeWidth={2.2} />
        {/* empirical regime map */}
        <Polyline points={empirical} opacity={OPACITY.fg} strokeWidth={2} />
        {/* slider Re marker */}
        <Polyline
          points={[
            [logRe, -1.0],
            [logRe, markY]
          ]}
          opacity={OPACITY.accent}
          dash="2 3"
          strokeWidth={STROKE_SECONDARY}
        />
        <Dot x={logRe} y={markY} r={3.5} opacity={OPACITY.fg} />
        {/* regime labels */}
        <Tex
          at={[-1.5, 1.95]}
          tex={String.raw`\text{creeping (Lamb)}`}
          size={FONT_TINY}
          opacity={OPACITY.dim}
          anchor="start"
        />
        <Tex
          at={[1.75, 0.95]}
          tex={String.raw`\text{vortex street}`}
          size={FONT_TINY}
          opacity={OPACITY.dim}
          anchor="start"
        />
        <Tex
          at={[3.0, 0.42]}
          tex={String.raw`\text{subcritical } C_D\approx1.2`}
          size={FONT_TINY}
          opacity={OPACITY.dim}
          anchor="middle"
        />
        <Tex
          at={[5.55, -0.85]}
          tex={String.raw`\text{drag crisis}`}
          size={FONT_TINY}
          opacity={OPACITY.dim}
          anchor="middle"
        />
        {/* axis labels */}
        <Tex
          at={[2.5, -0.92]}
          tex={String.raw`\log_{10} Re_d`}
          size={FONT_LABEL}
          opacity={OPACITY.fg}
          anchor="middle"
        />
        <Tex
          at={[-1.6, 1.4]}
          tex={String.raw`\log_{10} C_D`}
          size={FONT_LABEL}
          opacity={OPACITY.fg}
          anchor="start"
        />
        {/* decade tick labels */}
        {[
          [-1, '10^{-1}'],
          [0, '1'],
          [1, '10'],
          [2, '10^2'],
          [3, '10^3'],
          [4, '10^4'],
          [5, '10^5'],
          [6, '10^6']
        ].map(([x, lab]) => (
          <Tex
            key={x}
            at={[x, -0.78]}
            tex={String.raw`${lab}`}
            size={FONT_TINY}
            opacity={OPACITY.dim}
            anchor="middle"
          />
        ))}
      </Plot>
      {/* Readout row: the marker's Reynolds number and drag coefficient */}
      <div
        style={{
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          gap: 28,
          flexWrap: 'wrap',
          marginTop: 12
        }}
      >
        <span
          style={{
            display: 'inline-flex',
            alignItems: 'center',
            gap: 8,
            fontSize: FONT_TEX,
            opacity: OPACITY.dim
          }}
        >
          <KatexInline tex={String.raw`Re_d=${reTex}`} />
        </span>
        <span
          style={{
            display: 'inline-flex',
            alignItems: 'center',
            gap: 8,
            fontSize: FONT_TEX,
            opacity: OPACITY.fg
          }}
        >
          <KatexInline tex="C_D" />
          <span style={{ fontVariantNumeric: 'tabular-nums', fontSize: FONT_CONTROL }}>
            {markCD.toFixed(2)}
          </span>
        </span>
      </div>
      <div style={{ flex: 1, minWidth: 220 }}>
        <Slider
          label="Reynolds number Re"
          value={logRe}
          min={-1.3}
          max={6.0}
          step={0.05}
          onChange={setLogRe}
          format={() => fmtRe}
        />
      </div>
      <div
        style={{
          fontSize: FONT_SMALL,
          opacity: OPACITY.dim,
          textAlign: 'center',
          letterSpacing: LS_OPEN,
          textTransform: 'uppercase',
          marginTop: 6
        }}
      >
        Re ≲ 1 computed (Lamb–Oseen); Re ≳ 1 empirical regime map, schematic between points
      </div>
    </div>
  )
}

// NS.5: Stokes Drag: F = 6π η a v, linear drag-vs-velocity + creeping streamlines
export function NsStokesDrag() {
  const [playing, setPlaying] = React.useState(true)
  const t = useAnimationTime(playing, 1)
  const eta = 1.0
  const a = 0.5
  const U = 1.0
  // drag-vs-velocity line
  const vMax = 3.0
  const slope = 6 * Math.PI * eta * a
  const dragPts = [
    [0, 0],
    [vMax, slope * vMax]
  ]
  // True Stokes flow around a sphere (Re ≪ 1), θ from the flow (+x) axis:
  //   u_r = U cosθ [1 − 3/2(a/r) + 1/2(a/r)³],  u_θ = −U sinθ [1 − 3/4(a/r) − 1/4(a/r)³]
  // Streamlines are LEVEL SETS of the exact Stokes stream function
  //   ψ = U sin²θ (r²/2 − 3ar/4 + a³/4r),
  // solved per-x by bisection (ψ is monotone in |y| outside the sphere): closed
  // form, fore-aft symmetric by construction, no integration drift. Tracer time
  // comes from dt = ds/|u| along the contour with the exact velocity field.
  const streamlines = React.useMemo(() => {
    const fr = r => (r * r) / 2 - 0.75 * a * r + (a * a * a) / (4 * r)
    const psi = (x, y) => {
      const r = Math.hypot(x, y)
      return r <= a ? 0 : (U * y * y * fr(r)) / (r * r)
    }
    const vel = (x, y) => {
      const r = Math.hypot(x, y)
      if (r < a) return [0, 0]
      const ar = a / r
      const cos = x / r
      const sin = y / r
      const ur = U * cos * (1 - 1.5 * ar + 0.5 * ar * ar * ar)
      const ut = -U * sin * (1 - 0.75 * ar - 0.25 * ar * ar * ar)
      return [ur * cos - ut * sin, ur * sin + ut * cos]
    }
    const X0 = -3.9,
      X1 = 3.9,
      NX = 160,
      yTop = 3.6
    const seeds = [0.32, 0.6, 0.95, 1.35, 1.85, 2.45, 3.1]
    const lines = []
    seeds.forEach(y0 => {
      const psi0 = (U * y0 * y0) / 2 // far-upstream label ψ = U y₀²/2
      ;[1, -1].forEach(sgn => {
        const pts = []
        for (let i = 0; i <= NX; i++) {
          const x = X0 + (i / NX) * (X1 - X0)
          let lo = Math.abs(x) < a ? Math.sqrt(a * a - x * x) + 1e-6 : 1e-6
          let hi = yTop
          if (psi(x, hi) < psi0) continue
          for (let it = 0; it < 48; it++) {
            const mid = 0.5 * (lo + hi)
            if (psi(x, mid) < psi0) lo = mid
            else hi = mid
          }
          pts.push([x, sgn * 0.5 * (lo + hi)])
        }
        const times = [0]
        let T = 0
        for (let i = 1; i < pts.length; i++) {
          const ds = Math.hypot(pts[i][0] - pts[i - 1][0], pts[i][1] - pts[i - 1][1])
          const [ux, uy] = vel(0.5 * (pts[i][0] + pts[i - 1][0]), 0.5 * (pts[i][1] + pts[i - 1][1]))
          T += ds / Math.max(Math.hypot(ux, uy), 1e-6)
          times.push(T)
        }
        lines.push({ pts, times, T })
      })
    })
    return lines.filter(l => l.pts.length > 4 && l.T > 0)
  }, [])
  // tracer dot positions: parameterized by FLOW TIME so dots dwell where the fluid slows
  const period = 6.0
  const tracer = (l, i) => {
    const frac = (((t / period + i * 0.11) % 1) + 1) % 1
    const target = frac * l.T
    let k = 1
    while (k < l.times.length && l.times[k] < target) k++
    if (k >= l.pts.length) return null
    const a0 = l.pts[k - 1]
    const b0 = l.pts[k]
    const span = l.times[k] - l.times[k - 1] || 1
    const f = (target - l.times[k - 1]) / span
    return [a0[0] + f * (b0[0] - a0[0]), a0[1] + f * (b0[1] - a0[1])]
  }
  return (
    <div style={{ display: 'flex', gap: 16, flexWrap: 'wrap', alignItems: 'flex-start' }}>
      {/* Streamlines panel (primary) */}
      <div style={{ flex: '2 1 380px' }}>
        <Plot xRange={[-4, 4]} yRange={[-3.4, 3.4]} width={460} height={396}>
          <Axes step={2} showGrid={false} showTicks={false} showOrigin={false} />
          {/* streamlines */}
          {streamlines.map((l, i) => (
            <Polyline key={i} points={l.pts} opacity={OPACITY.dim} strokeWidth={0.9} />
          ))}
          {/* advected tracers */}
          {streamlines.map((l, i) => {
            const p = tracer(l, i)
            return p ? <Dot key={`d${i}`} x={p[0]} y={p[1]} r={2.2} opacity={OPACITY.fg} /> : null
          })}
          {/* sphere on top */}
          <CircleSh cx={0} cy={0} r={a} fillOpacity={0.18} opacity={OPACITY.fg} />
          <Tex
            at={[-3.8, 0.25]}
            tex={String.raw`U_\infty \rightarrow`}
            size={FONT_SMALL}
            opacity={OPACITY.dim}
            anchor="start"
          />
          <Tex
            at={[3.8, 3.0]}
            tex={String.raw`\text{fore-aft symmetric}`}
            size={FONT_TINY}
            opacity={OPACITY.dim}
            anchor="end"
          />
          <Tex
            at={[0.1, -0.62]}
            tex={String.raw`a`}
            size={FONT_SMALL}
            opacity={OPACITY.dim}
            anchor="middle"
          />
          <Tex
            at={[-3.8, -3.05]}
            tex={String.raw`\psi=U\sin^2\!\theta\,\bigl(\tfrac{r^2}{2}-\tfrac{3ar}{4}+\tfrac{a^3}{4r}\bigr)`}
            size={FONT_TINY}
            opacity={OPACITY.dim}
            anchor="start"
          />
        </Plot>
        <div
          style={{
            fontSize: FONT_SMALL,
            opacity: OPACITY.dim,
            textAlign: 'center',
            letterSpacing: LS_OPEN,
            textTransform: 'uppercase',
            marginTop: 4
          }}
        >
          Creeping-flow streamlines: level sets of the exact Stokes stream function
        </div>
      </div>
      {/* Drag vs velocity panel */}
      <div style={{ flex: '1 1 240px' }}>
        <Plot xRange={[-0.2, 3.5]} yRange={[-0.5, 10]} width={300} height={440}>
          <Axes step={2} showGrid={true} showTicks={true} />
          <Polyline points={dragPts} opacity={OPACITY.fg} strokeWidth={2} />
          <Tex
            at={[1.4, 7.2]}
            tex={String.raw`F=6\pi\eta a v`}
            size={FONT_LABEL}
            opacity={OPACITY.fg}
            anchor="start"
          />
          <Tex
            at={[1.4, 5.6]}
            tex={String.raw`C_D=\tfrac{24}{Re}`}
            size={FONT_LABEL}
            opacity={OPACITY.accent}
            anchor="start"
          />
          <Tex
            at={[3.1, 0.5]}
            tex={String.raw`v`}
            size={FONT_LABEL}
            opacity={OPACITY.dim}
            anchor="start"
          />
          <Tex
            at={[0.1, 9.5]}
            tex={String.raw`F`}
            size={FONT_LABEL}
            opacity={OPACITY.dim}
            anchor="start"
          />
        </Plot>
        <div
          style={{
            fontSize: FONT_SMALL,
            opacity: OPACITY.dim,
            textAlign: 'center',
            letterSpacing: LS_OPEN,
            textTransform: 'uppercase',
            marginTop: 4
          }}
        >
          drag linear in v at Re ≪ 1
        </div>
      </div>
      <div style={{ flexBasis: '100%', marginTop: 4 }}>
        <PlayPause playing={playing} onToggle={() => setPlaying(p => !p)} onReset={() => {}} />
      </div>
    </div>
  )
}

// NS.6: Blasius Boundary Layer: solve f''' + (1/2) f f'' = 0 with rk4Integrate (shooting)
export function NsBlasiusLayer() {
  const [playing, setPlaying] = React.useState(true)
  const t = useAnimationTime(playing, 1)
  // Blasius ODE as first-order system: y = [f, f', f''], y' = [f', f'', -(1/2) f f'']
  const f_ode = (_t, y) => [y[1], y[2], -0.5 * y[0] * y[2]]
  const fpp0 = 0.33206 // shooting constant f''(0): the wall shear
  const etaMax = 8.0
  const N = 800
  const deta = etaMax / N
  const profilePts = []
  let y = [0, 0, fpp0]
  profilePts.push([y[1], 0]) // u/U = f'(0) = 0
  for (let i = 0; i < N; i++) {
    y = rk4Integrate(f_ode, y, i * deta, (i + 1) * deta, 1)
    profilePts.push([Math.min(y[1], 1.0), (i + 1) * deta])
  }
  const eta99 = profilePts.find(([u]) => u >= 0.99)?.[1] ?? 5.0
  // O(1) lookup of f'(η) on the uniform η grid
  const fpArr = profilePts.map(p => p[0])
  const fpOf = e => fpArr[Math.min(N, Math.max(0, Math.round(e / deta)))]

  // Physical panel: δ(x) = δ99·√(x), self-similar profiles, tracers that slow near the wall
  const delta = x => Math.sqrt(Math.max(x, 1e-4)) // ∝ √(νx/U)
  const profW = 1.15 // visual width of one u/U = 1 profile
  const station = xs => {
    const d = delta(xs)
    const pts = []
    for (let s = 0; s <= 1.0001; s += 0.05) {
      const yy = s * d * (eta99 / 5) * 5 // y from 0 to δ99
      const eta = (yy / d) * 5
      pts.push([xs + fpOf(eta) * profW, yy])
    }
    return pts
  }
  const edgePts = []
  for (let xs = 0.4; xs <= 9.6; xs += 0.2) edgePts.push([xs + profW, delta(xs) * (eta99 / 5)])
  // advected tracers: fixed height, speed = U f'(η(x)); deeper relative to δ as it thickens
  const period = 8.0
  const seeds = [0.35, 0.7, 1.15, 1.7, 2.4]
  const advance = (y0, tau) => {
    let x = 0.4
    let acc = 0
    const dtp = 0.03
    while (acc < tau && x < 9.7) {
      const d = delta(x)
      const u = fpOf((y0 / d) * 5) + 0.02
      x += u * dtp
      acc += dtp
    }
    return x
  }
  const tracers = []
  seeds.forEach((y0, i) => {
    for (let ph = 0; ph < 2; ph++) {
      const frac = (((t / period + (i * 0.13 + ph * 0.5)) % 1) + 1) % 1
      const x = advance(y0, frac * 13)
      if (x < 9.6) tracers.push([x, y0 * (eta99 / 5)])
    }
  })

  return (
    <div style={{ display: 'flex', gap: 16, flexWrap: 'wrap', alignItems: 'flex-start' }}>
      {/* Physical flat-plate panel */}
      <div style={{ flex: '2 1 360px' }}>
        <Plot xRange={[0, 10]} yRange={[-0.4, 4.4]} width={460} height={440}>
          {/* plate */}
          <Polyline
            points={[
              [0.4, 0],
              [9.6, 0]
            ]}
            opacity={OPACITY.accent}
            strokeWidth={2}
          />
          {/* boundary-layer edge δ(x) */}
          <Polyline
            points={edgePts}
            opacity={OPACITY.dim}
            dash="4 4"
            strokeWidth={STROKE_SECONDARY}
          />
          {/* self-similar profiles at stations: same shape, taller downstream */}
          {[1.5, 3.5, 6, 8.5].map(xs => (
            <Polyline key={xs} points={station(xs)} opacity={OPACITY.fg} strokeWidth={1.4} />
          ))}
          {/* advected tracers */}
          {tracers.map((p, i) => (
            <Dot key={i} x={p[0]} y={p[1]} r={2.2} opacity={OPACITY.fg} />
          ))}
          <Tex
            at={[0.2, 3.9]}
            tex={String.raw`U_\infty \rightarrow`}
            size={FONT_SMALL}
            opacity={OPACITY.dim}
            anchor="start"
          />
          <Tex
            at={[9.6, 3.7]}
            tex={String.raw`\delta(x)\propto\sqrt{\tfrac{\nu x}{U}}`}
            size={FONT_SMALL}
            opacity={OPACITY.dim}
            anchor="end"
          />
          <Tex
            at={[5, -0.32]}
            tex={String.raw`x\ \text{(distance from leading edge)}`}
            size={FONT_TINY}
            opacity={OPACITY.dim}
            anchor="middle"
          />
        </Plot>
        <div
          style={{
            fontSize: FONT_SMALL,
            opacity: OPACITY.dim,
            textAlign: 'center',
            letterSpacing: LS_OPEN,
            textTransform: 'uppercase',
            marginTop: 4
          }}
        >
          Layer thickens as √x; every profile is the same shape
        </div>
      </div>
      {/* Self-similar profile panel */}
      <div style={{ flex: '1 1 240px' }}>
        <Plot xRange={[-0.05, 1.2]} yRange={[-0.2, 8.5]} width={300} height={440}>
          <Axes step={1} showGrid={true} showTicks={true} showOrigin={true} />
          <Polyline points={profilePts} opacity={OPACITY.fg} strokeWidth={2} />
          <Polyline
            points={[
              [1, 0],
              [1, etaMax]
            ]}
            opacity={OPACITY.faint}
            dash="4 4"
            strokeWidth={STROKE_SECONDARY}
          />
          <Polyline
            points={[
              [0, eta99],
              [1.05, eta99]
            ]}
            opacity={OPACITY.accent}
            dash="3 3"
            strokeWidth={STROKE_SECONDARY}
          />
          <Dot x={1.0} y={eta99} r={3} opacity={OPACITY.accent} />
          <Tex
            at={[0.05, 8.1]}
            tex={String.raw`\eta=y\sqrt{\tfrac{U}{\nu x}}`}
            size={FONT_LABEL}
            opacity={OPACITY.dim}
            anchor="start"
          />
          <Tex
            at={[1.07, eta99 + 0.3]}
            tex={String.raw`\delta_{99}`}
            size={FONT_SMALL}
            opacity={OPACITY.accent}
            anchor="end"
          />
          <Tex
            at={[0.5, -0.12]}
            tex={String.raw`u/U=f'(\eta)`}
            size={FONT_SMALL}
            opacity={OPACITY.dim}
            anchor="middle"
          />
          <Tex
            at={[0.06, 0.55]}
            tex={String.raw`f''(0)=0.332`}
            size={FONT_TINY}
            opacity={OPACITY.dim}
            anchor="start"
          />
        </Plot>
        <div
          style={{
            fontSize: FONT_SMALL,
            opacity: OPACITY.dim,
            textAlign: 'center',
            letterSpacing: LS_OPEN,
            textTransform: 'uppercase',
            marginTop: 4
          }}
        >
          all x collapse to one curve · rk4 of f‴ + ½ f f″ = 0
        </div>
      </div>
      <div style={{ flexBasis: '100%', marginTop: 4 }}>
        <PlayPause playing={playing} onToggle={() => setPlaying(p => !p)} onReset={() => {}} />
      </div>
    </div>
  )
}

// NS.7: Kolmogorov -5/3 Energy Spectrum: log-log inertial-range scaling law
export function NsKolmogorovSpectrum() {
  // log10 k axis from -1 to 5; inertial range 1 to 4 in log10 k
  const kLogMin = -0.5
  const kLogMax = 5.5
  const inertialStart = 1.0
  const inertialEnd = 4.2
  // E(k) ~ q^{2/3} k^{-5/3}: log10 E = C - (5/3) log10 k, C chosen for display
  const C = 4.5
  const inertialPts = []
  for (let i = 0; i <= 50; i++) {
    const logk = inertialStart + (i / 50) * (inertialEnd - inertialStart)
    const logE = C - (5 / 3) * logk
    inertialPts.push([logk, logE])
  }
  // Energy-containing range (flat/rising left side): schematic
  const energyPts = [
    [kLogMin, 2.6],
    [0.3, 3.4],
    [0.7, 3.8],
    [inertialStart, C - (5 / 3) * inertialStart]
  ]
  // Dissipation range (steep drop): schematic
  const dissipPts = [
    [inertialEnd, C - (5 / 3) * inertialEnd],
    [inertialEnd + 0.5, C - (5 / 3) * inertialEnd - 1.2],
    [kLogMax, C - (5 / 3) * inertialEnd - 3.0]
  ]

  return (
    <Plot xRange={[-0.8, 6.2]} yRange={[-1.5, 5.5]} width={620} height={440}>
      <Axes step={1} showGrid={true} showTicks={true} showOrigin={false} />
      {/* energy-containing range */}
      <Polyline points={energyPts} opacity={OPACITY.dim} strokeWidth={STROKE_PRIMARY} dash="4 3" />
      {/* -5/3 inertial range */}
      <Polyline points={inertialPts} opacity={OPACITY.fg} strokeWidth={2.5} />
      {/* dissipation range */}
      <Polyline points={dissipPts} opacity={OPACITY.dim} strokeWidth={STROKE_PRIMARY} dash="4 3" />
      {/* vertical range boundaries */}
      <Polyline
        points={[
          [inertialStart, -1.2],
          [inertialStart, 5.0]
        ]}
        opacity={OPACITY.faint}
        dash="3 3"
        strokeWidth={STROKE_SECONDARY}
      />
      <Polyline
        points={[
          [inertialEnd, -1.2],
          [inertialEnd, 5.0]
        ]}
        opacity={OPACITY.faint}
        dash="3 3"
        strokeWidth={STROKE_SECONDARY}
      />
      {/* slope triangle: 1 decade in k → 5/3 decades drop in E, hypotenuse on the line */}
      <Polyline
        points={[
          [2.5, C - (5 / 3) * 2.5],
          [3.5, C - (5 / 3) * 2.5],
          [3.5, C - (5 / 3) * 3.5]
        ]}
        opacity={OPACITY.accent}
        strokeWidth={STROKE_SECONDARY}
      />
      <Tex
        at={[3.0, C - (5 / 3) * 2.5 + 0.12]}
        tex={String.raw`1`}
        size={FONT_TINY}
        opacity={OPACITY.accent}
        anchor="middle"
      />
      <Tex
        at={[3.58, C - (5 / 3) * 3.0]}
        tex={String.raw`\tfrac{5}{3}`}
        size={FONT_TINY}
        opacity={OPACITY.accent}
        anchor="start"
      />
      <Tex
        at={[2.05, C - (5 / 3) * 2.0 + 0.2]}
        tex={String.raw`E(k)=C\,\varepsilon^{2/3}k^{-5/3}`}
        size={FONT_LABEL}
        opacity={OPACITY.fg}
        anchor="start"
      />
      {/* region labels */}
      <Tex
        at={[-0.5, 4.9]}
        tex={String.raw`\text{energy-containing}`}
        size={FONT_TINY}
        opacity={OPACITY.dim}
        anchor="start"
      />
      <Tex
        at={[1.9, 4.5]}
        tex={String.raw`\text{inertial range}`}
        size={FONT_TINY}
        opacity={OPACITY.fg}
        anchor="start"
      />
      <Tex
        at={[4.25, 3.4]}
        tex={String.raw`\text{dissipation}`}
        size={FONT_TINY}
        opacity={OPACITY.dim}
        anchor="start"
      />
      {/* scale markers: integral scale and Kolmogorov scale */}
      <Tex
        at={[inertialStart, -1.28]}
        tex={String.raw`k\sim 1/L`}
        size={FONT_TINY}
        opacity={OPACITY.dim}
        anchor="middle"
      />
      <Tex
        at={[inertialStart, 5.0]}
        tex={String.raw`\text{integral } L`}
        size={FONT_TINY}
        opacity={OPACITY.faint}
        anchor="middle"
      />
      <Tex
        at={[inertialEnd, -1.28]}
        tex={String.raw`k\sim 1/\eta`}
        size={FONT_TINY}
        opacity={OPACITY.dim}
        anchor="middle"
      />
      <Tex
        at={[inertialEnd, 5.0]}
        tex={String.raw`\eta=(\nu^3/\varepsilon)^{1/4}`}
        size={FONT_TINY}
        opacity={OPACITY.faint}
        anchor="middle"
      />
      {/* axis labels */}
      <Tex
        at={[2.7, -1.45]}
        tex={String.raw`\log_{10} k`}
        size={FONT_LABEL}
        opacity={OPACITY.fg}
        anchor="middle"
      />
      <Tex
        at={[-0.7, 4.3]}
        tex={String.raw`\log_{10} E(k)`}
        size={FONT_LABEL}
        opacity={OPACITY.fg}
        anchor="start"
      />
      {/* honesty note */}
      <Tex
        at={[-0.7, 5.4]}
        tex={String.raw`C\approx1.5\ \text{(Kolmogorov const); }-5/3\text{ is exact, tails schematic}`}
        size={FONT_TINY}
        opacity={OPACITY.dim}
        anchor="start"
      />
    </Plot>
  )
}

// CLASSICAL MECHANICS · LINEAR ELASTICITY

// 06.10.1 Strain decomposition: three panels showing expansion, rotation, shear
export function CM_LE_StrainDecomposition() {
  const W = 540
  const H = 220
  const panW = W / 3
  const cx = panW / 2
  const cy = H / 2 - 4
  const s = 44
  const arrowLen = 20

  const expScale = 1.35
  const ang = (20 * Math.PI) / 180
  const rc = Math.cos(ang),
    rs = Math.sin(ang)
  function rot(x, y) {
    return [rc * x - rs * y, rs * x + rc * y]
  }
  const rotPts = [rot(-s, -s), rot(s, -s), rot(s, s), rot(-s, s)]
  const sh = 0.42
  function shr(x, y) {
    return [x + sh * y, y]
  }
  const shrPts = [shr(-s, -s), shr(s, -s), shr(s, s), shr(-s, s)]
  const expPts = [
    [-s * expScale, -s * expScale],
    [s * expScale, -s * expScale],
    [s * expScale, s * expScale],
    [-s * expScale, s * expScale]
  ]

  function polyStr(pts, ox, oy) {
    return pts.map(([x, y]) => `${ox + x},${oy + y}`).join(' ')
  }

  const expArrows = [
    { x1: cx, y1: cy - s * expScale, x2: cx, y2: cy - s * expScale - arrowLen },
    { x1: cx, y1: cy + s * expScale, x2: cx, y2: cy + s * expScale + arrowLen },
    { x1: cx - s * expScale, y1: cy, x2: cx - s * expScale - arrowLen, y2: cy },
    { x1: cx + s * expScale, y1: cy, x2: cx + s * expScale + arrowLen, y2: cy }
  ]

  const offR = panW
  const offSh = panW * 2
  const rotArrows = [
    {
      x1: offR + cx + rotPts[0][0],
      y1: cy + rotPts[0][1],
      x2: offR + cx + rotPts[0][0] + 13,
      y2: cy + rotPts[0][1] - 8
    },
    {
      x1: offR + cx + rotPts[1][0],
      y1: cy + rotPts[1][1],
      x2: offR + cx + rotPts[1][0] + 8,
      y2: cy + rotPts[1][1] + 13
    },
    {
      x1: offR + cx + rotPts[2][0],
      y1: cy + rotPts[2][1],
      x2: offR + cx + rotPts[2][0] - 13,
      y2: cy + rotPts[2][1] + 8
    },
    {
      x1: offR + cx + rotPts[3][0],
      y1: cy + rotPts[3][1],
      x2: offR + cx + rotPts[3][0] - 8,
      y2: cy + rotPts[3][1] - 13
    }
  ]

  return (
    <svg
      viewBox={`0 0 ${W} ${H}`}
      width="100%"
      preserveAspectRatio="xMidYMid meet"
      style={{ display: 'block', margin: '1.2rem auto', maxWidth: 540 }}
    >
      <defs>
        <marker id="le-arr" markerWidth="6" markerHeight="6" refX="5" refY="3" orient="auto">
          <path d="M0,0 L6,3 L0,6 Z" fill={FG} fillOpacity={OPACITY.fg} />
        </marker>
      </defs>
      <line
        x1={panW}
        y1={16}
        x2={panW}
        y2={H - 16}
        stroke={FG}
        strokeOpacity={OPACITY.faint}
        strokeWidth={STROKE_SECONDARY}
      />
      <line
        x1={panW * 2}
        y1={16}
        x2={panW * 2}
        y2={H - 16}
        stroke={FG}
        strokeOpacity={OPACITY.faint}
        strokeWidth={STROKE_SECONDARY}
      />

      <TexPx
        x={W / 2}
        y={14}
        anchor="middle"
        tex={'W = \\tfrac{1}{3}\\Theta g + R + \\Sigma\\ (\\text{three irreducible parts})'}
        size={FONT_SMALL}
        width={451}
      />

      {/* Panel 1: Expansion */}
      <polygon
        points={polyStr(
          [
            [-s, -s],
            [s, -s],
            [s, s],
            [-s, s]
          ],
          cx,
          cy
        )}
        fill="none"
        stroke={FG}
        strokeOpacity={OPACITY.faint}
        strokeWidth={STROKE_SECONDARY}
        strokeDasharray="4 3"
      />
      <polygon
        points={polyStr(expPts, cx, cy)}
        fill={FG}
        fillOpacity={0.06}
        stroke={FG}
        strokeOpacity={OPACITY.accent}
        strokeWidth={STROKE_PRIMARY}
      />
      {expArrows.map((a, i) => (
        <line
          key={i}
          x1={a.x1}
          y1={a.y1}
          x2={a.x2}
          y2={a.y2}
          stroke={FG}
          strokeOpacity={OPACITY.fg}
          strokeWidth={STROKE_PRIMARY}
          markerEnd="url(#le-arr)"
        />
      ))}
      <TexPx
        x={cx}
        y={H - 24}
        anchor="middle"
        tex={'\\text{Expansion }(\\Theta)'}
        size={FONT_SMALL}
      />
      <text
        x={cx}
        y={H - 9}
        textAnchor="middle"
        fontSize={FONT_TINY}
        fill={FG}
        fillOpacity={OPACITY.faint}
        fontFamily={FONT_FAMILY}
      >
        area × 1.8
      </text>

      {/* Panel 2: Rotation */}
      <polygon
        points={polyStr(
          [
            [-s, -s],
            [s, -s],
            [s, s],
            [-s, s]
          ],
          offR + cx,
          cy
        )}
        fill="none"
        stroke={FG}
        strokeOpacity={OPACITY.faint}
        strokeWidth={STROKE_SECONDARY}
        strokeDasharray="4 3"
      />
      <polygon
        points={polyStr(rotPts, offR + cx, cy)}
        fill={FG}
        fillOpacity={0.06}
        stroke={FG}
        strokeOpacity={OPACITY.accent}
        strokeWidth={STROKE_PRIMARY}
      />
      {rotArrows.map((a, i) => (
        <line
          key={i}
          x1={a.x1}
          y1={a.y1}
          x2={a.x2}
          y2={a.y2}
          stroke={FG}
          strokeOpacity={OPACITY.fg}
          strokeWidth={STROKE_PRIMARY}
          markerEnd="url(#le-arr)"
        />
      ))}
      <text
        x={offR + cx}
        y={H - 24}
        textAnchor="middle"
        fontSize={FONT_SMALL}
        fill={FG}
        fillOpacity={OPACITY.dim}
        fontFamily={FONT_FAMILY}
      >
        Rotation (R)
      </text>
      <text
        x={offR + cx}
        y={H - 9}
        textAnchor="middle"
        fontSize={FONT_TINY}
        fill={FG}
        fillOpacity={OPACITY.faint}
        fontFamily={FONT_FAMILY}
      >
        20° · area fixed
      </text>

      {/* Panel 3: Shear */}
      <polygon
        points={polyStr(
          [
            [-s, -s],
            [s, -s],
            [s, s],
            [-s, s]
          ],
          offSh + cx,
          cy
        )}
        fill="none"
        stroke={FG}
        strokeOpacity={OPACITY.faint}
        strokeWidth={STROKE_SECONDARY}
        strokeDasharray="4 3"
      />
      <polygon
        points={polyStr(shrPts, offSh + cx, cy)}
        fill={FG}
        fillOpacity={0.06}
        stroke={FG}
        strokeOpacity={OPACITY.accent}
        strokeWidth={STROKE_PRIMARY}
      />
      <line
        x1={offSh + cx + sh * s}
        y1={cy - s}
        x2={offSh + cx + sh * s + arrowLen}
        y2={cy - s}
        stroke={FG}
        strokeOpacity={OPACITY.fg}
        strokeWidth={STROKE_PRIMARY}
        markerEnd="url(#le-arr)"
      />
      <line
        x1={offSh + cx - sh * s}
        y1={cy + s}
        x2={offSh + cx - sh * s - arrowLen}
        y2={cy + s}
        stroke={FG}
        strokeOpacity={OPACITY.fg}
        strokeWidth={STROKE_PRIMARY}
        markerEnd="url(#le-arr)"
      />
      <TexPx
        x={offSh + cx}
        y={H - 24}
        anchor="middle"
        tex={'\\text{Shear }(\\Sigma)'}
        size={FONT_SMALL}
      />
      <text
        x={offSh + cx}
        y={H - 9}
        textAnchor="middle"
        fontSize={FONT_TINY}
        fill={FG}
        fillOpacity={OPACITY.faint}
        fontFamily={FONT_FAMILY}
      >
        det = 1 · area fixed
      </text>
    </svg>
  )
}

// 06.10.2 Shear ellipse: unit circle stretched at constant area
export function CM_LE_ShearEllipse() {
  const [gamma, setGamma] = React.useState(0.4)
  const W = 360
  const H = 300
  const cx = W / 2,
    cy = H / 2
  const r = 56
  // Volume-preserving (area-preserving in 2D) shear: principal stretches e^γ and e^−γ.
  // Their product is exactly 1, so the ellipse area π·rx·ry = π·r² for every γ.
  const rx = r * Math.exp(gamma)
  const ry = r * Math.exp(-gamma)
  const areaRatio = (rx * ry) / (r * r) // ≡ 1 by construction

  const N = 16
  const pts = Array.from({ length: N }, (_, i) => {
    const theta = (2 * Math.PI * i) / N
    return [Math.cos(theta), Math.sin(theta)]
  })

  return (
    <div>
      <svg
        viewBox={`0 0 ${W} ${H}`}
        width="100%"
        preserveAspectRatio="xMidYMid meet"
        style={{ display: 'block', margin: '1.2rem auto', maxWidth: 360 }}
      >
        <defs>
          <marker id="le-arr2" markerWidth="6" markerHeight="6" refX="5" refY="3" orient="auto">
            <path d="M0,0 L6,3 L0,6 Z" fill={FG} fillOpacity={OPACITY.fg} />
          </marker>
        </defs>
        <circle
          cx={cx}
          cy={cy}
          r={r}
          fill="none"
          stroke={FG}
          strokeOpacity={OPACITY.faint}
          strokeWidth={STROKE_SECONDARY}
          strokeDasharray="4 3"
        />
        <ellipse
          cx={cx}
          cy={cy}
          rx={rx}
          ry={ry}
          fill={FG}
          fillOpacity={0.06}
          stroke={FG}
          strokeOpacity={OPACITY.accent}
          strokeWidth={2}
        />
        {pts.map(([ux, uy], i) => {
          const ox = cx + r * ux,
            oy = cy + r * uy
          const nx = cx + rx * ux,
            ny = cy + ry * uy
          const ddx = nx - ox,
            ddy = ny - oy
          if (Math.hypot(ddx, ddy) < 2) return null
          return (
            <line
              key={i}
              x1={ox}
              y1={oy}
              x2={nx}
              y2={ny}
              stroke={FG}
              strokeOpacity={OPACITY.dim}
              strokeWidth={1.2}
              markerEnd="url(#le-arr2)"
            />
          )
        })}
        <line
          x1={cx - r - 16}
          y1={cy}
          x2={cx + r + 16}
          y2={cy}
          stroke={FG}
          strokeOpacity={OPACITY.faint}
          strokeWidth={STROKE_SECONDARY}
        />
        <line
          x1={cx}
          y1={cy - r - 16}
          x2={cx}
          y2={cy + r + 16}
          stroke={FG}
          strokeOpacity={OPACITY.faint}
          strokeWidth={STROKE_SECONDARY}
        />
        <TexPx x={cx + rx + 5} y={cy + 4} tex={'\\times e^{\\gamma}'} size={FONT_TINY} />
        <TexPx x={cx + 6} y={cy - ry - 6} tex={'\\times e^{-\\gamma}'} size={FONT_TINY} />
        <text
          x={12}
          y={20}
          fontSize={FONT_LABEL}
          fill={FG}
          fillOpacity={OPACITY.fg}
          fontFamily={FONT_FAMILY}
        >
          {`γ = ${gamma.toFixed(2)}`}
        </text>
        <text
          x={W - 12}
          y={20}
          textAnchor="end"
          fontSize={FONT_LABEL}
          fill={FG}
          fillOpacity={OPACITY.accent}
          fontFamily={FONT_FAMILY}
        >
          {`A / A₀ = ${areaRatio.toFixed(3)}`}
        </text>
        <TexPx
          x={cx}
          y={H - 6}
          anchor="middle"
          tex={'\\text{Pure shear }\\Sigma\\text{: area exactly conserved at every }\\gamma'}
          size={FONT_TINY}
          width={517}
        />
      </svg>
      <Slider
        label="γ (shear)"
        value={gamma}
        min={0}
        max={0.8}
        step={0.02}
        onChange={setGamma}
        format={v => v.toFixed(2)}
      />
    </div>
  )
}

// 06.10.3 Stress traction on a tilted surface
export function CM_LE_StressTraction() {
  const [tiltDeg, setTiltDeg] = React.useState(30)
  const theta = (tiltDeg * Math.PI) / 180
  const normalMag = Math.cos(theta) * Math.cos(theta)
  const shearMag = Math.sin(theta) * Math.cos(theta)

  const W = 340
  const H = 280
  const bx1 = 120,
    bx2 = 220,
    by1 = 60,
    by2 = 200
  const cpCx = (bx1 + bx2) / 2,
    cpCy = (by1 + by2) / 2
  const cpLen = 60
  const dx = cpLen * Math.cos(Math.PI / 2 - theta)
  const dy = cpLen * Math.sin(Math.PI / 2 - theta)
  const nSx = Math.sin(theta),
    nSy = -Math.cos(theta)
  const totLen = Math.cos(theta) * 62

  return (
    <div style={{ maxWidth: 340, margin: '1rem auto' }}>
      <Slider
        label="Tilt angle"
        value={tiltDeg}
        min={5}
        max={80}
        step={5}
        onChange={setTiltDeg}
        format={v => `${v}°`}
      />
      <svg viewBox={`0 0 ${W} ${H}`} width="100%" preserveAspectRatio="xMidYMid meet">
        <defs>
          <marker id="le-arr3" markerWidth="7" markerHeight="7" refX="6" refY="3.5" orient="auto">
            <path d="M0,0 L7,3.5 L0,7 Z" fill={FG} fillOpacity={OPACITY.fg} />
          </marker>
          <marker id="le-arr3a" markerWidth="7" markerHeight="7" refX="6" refY="3.5" orient="auto">
            <path d="M0,0 L7,3.5 L0,7 Z" fill={FG} fillOpacity={OPACITY.accent} />
          </marker>
        </defs>
        <rect
          x={bx1}
          y={by1}
          width={bx2 - bx1}
          height={by2 - by1}
          fill={FG}
          fillOpacity={0.04}
          stroke={FG}
          strokeOpacity={OPACITY.dim}
          strokeWidth={STROKE_PRIMARY}
        />
        {[-30, 0, 30].map((ddx, i) => (
          <line
            key={i}
            x1={cpCx + ddx}
            y1={by1 - 22}
            x2={cpCx + ddx}
            y2={by1 - 2}
            stroke={FG}
            strokeOpacity={OPACITY.accent}
            strokeWidth={STROKE_PRIMARY}
            markerEnd="url(#le-arr3a)"
          />
        ))}
        <line
          x1={cpCx - dx}
          y1={cpCy + dy}
          x2={cpCx + dx}
          y2={cpCy - dy}
          stroke={FG}
          strokeOpacity={OPACITY.fg}
          strokeWidth={2}
          strokeDasharray="6 3"
        />
        <line
          x1={cpCx}
          y1={cpCy}
          x2={cpCx}
          y2={cpCy - totLen}
          stroke={FG}
          strokeOpacity={OPACITY.fg}
          strokeWidth={2.5}
          markerEnd="url(#le-arr3)"
        />
        <line
          x1={cpCx}
          y1={cpCy}
          x2={cpCx + nSx * normalMag * 62}
          y2={cpCy + nSy * normalMag * 62}
          stroke={FG}
          strokeOpacity={OPACITY.accent}
          strokeWidth={STROKE_PRIMARY}
          strokeDasharray="4 2"
          markerEnd="url(#le-arr3a)"
        />
        <text
          x={cpCx + 5}
          y={cpCy - totLen - 5}
          fontSize={FONT_SMALL}
          fill={FG}
          fillOpacity={OPACITY.fg}
          fontFamily={FONT_FAMILY}
        >
          T·n
        </text>
        <text
          x={cpCx + nSx * normalMag * 62 + 5}
          y={cpCy + nSy * normalMag * 62}
          fontSize={FONT_TINY}
          fill={FG}
          fillOpacity={OPACITY.accent}
          fontFamily={FONT_FAMILY}
        >
          normal
        </text>
        <text
          x={W / 2}
          y={H - 8}
          textAnchor="middle"
          fontSize={FONT_TINY}
          fill={FG}
          fillOpacity={OPACITY.dim}
          fontFamily={FONT_FAMILY}
        >
          {`θ=${tiltDeg}°  normal=cos²θ=${normalMag.toFixed(2)}  shear=sinθcosθ=${shearMag.toFixed(2)}`}
        </text>
      </svg>
    </div>
  )
}

// 06.10.4 Hooke's law stress-strain curve with four landmark points
export function CM_LE_HookeCurve() {
  // Qualitative ductile-metal stress–strain curve (normalized axes, no material units).
  // Landmark ordering follows the physics: stress rises linearly through the
  // proportional limit, yields, hardens to the ultimate strength (global max), then
  // engineering stress falls during necking to fracture at the largest strain.
  const propX = 0.06,
    propY = 0.6 // end of the linear Hooke region
  const yieldX = 0.13,
    yieldY = 0.88 // onset of permanent (plastic) flow
  const ultX = 0.55,
    ultY = 1.35 // ultimate tensile strength: the peak
  const rupX = 0.8,
    rupY = 1.05 // fracture: below the peak (necking), at the largest strain

  const pts = [
    [0, 0],
    [0.03, 0.3],
    [propX, propY],
    [0.085, 0.76],
    [0.11, 0.85],
    [yieldX, yieldY],
    [0.155, 0.86],
    [0.22, 0.9],
    [0.3, 1.05],
    [0.4, 1.22],
    [0.5, 1.33],
    [ultX, ultY],
    [0.64, 1.3],
    [0.72, 1.19],
    [rupX, rupY]
  ]

  const landmarks = [
    [propX, propY],
    [yieldX, yieldY],
    [ultX, ultY],
    [rupX, rupY]
  ]

  return (
    <Plot xRange={[-0.05, 0.9]} yRange={[-0.22, 1.7]} width={560} height={440}>
      <Axes step={0.5} showGrid={false} showTicks={false} showOrigin={true} />

      {/* elastic | plastic divider at the yield point */}
      <Polyline
        points={[
          [yieldX, 0],
          [yieldX, 1.62]
        ]}
        opacity={OPACITY.faint}
        strokeWidth={STROKE_SECONDARY}
        dash="3 4"
      />
      <Tex
        at={[yieldX / 2, -0.16]}
        tex={String.raw`\text{elastic}`}
        size={FONT_TINY}
        anchor="middle"
        opacity={OPACITY.dim}
      />
      <Tex
        at={[(yieldX + 0.88) / 2, -0.16]}
        tex={String.raw`\text{plastic}`}
        size={FONT_TINY}
        anchor="middle"
        opacity={OPACITY.dim}
      />

      {/* main curve, then the linear Hooke region highlighted */}
      <Polyline points={pts} opacity={OPACITY.fg} strokeWidth={2.5} />
      <Polyline
        points={[
          [0, 0],
          [propX, propY]
        ]}
        opacity={OPACITY.accent}
        strokeWidth={3.5}
      />

      {landmarks.map(([x, y], i) => (
        <Polyline
          key={`d${i}`}
          points={[
            [x, 0],
            [x, y]
          ]}
          opacity={OPACITY.faint}
          strokeWidth={STROKE_SECONDARY}
          dash="4 3"
        />
      ))}
      {landmarks.map(([x, y], i) => (
        <Dot key={`m${i}`} x={x} y={y} r={4} />
      ))}

      <Tex
        at={[0.21, 0.42]}
        tex={String.raw`\text{Hooke (linear)}`}
        size={FONT_TINY}
        anchor="middle"
        opacity={OPACITY.accent}
      />
      <Tex
        at={[propX - 0.005, propY - 0.2]}
        tex={String.raw`\text{prop. limit}`}
        size={FONT_TINY}
        anchor="middle"
        opacity={OPACITY.dim}
      />
      <Tex
        at={[yieldX + 0.02, yieldY + 0.15]}
        tex={String.raw`\text{yield}`}
        size={FONT_TINY}
        anchor="middle"
        opacity={OPACITY.dim}
      />
      <Tex
        at={[ultX, ultY + 0.15]}
        tex={String.raw`\text{ultimate}`}
        size={FONT_TINY}
        anchor="middle"
        opacity={OPACITY.dim}
      />
      <Tex
        at={[rupX, rupY - 0.2]}
        tex={String.raw`\text{fracture}`}
        size={FONT_TINY}
        anchor="middle"
        opacity={OPACITY.dim}
      />
      <Tex
        at={[0.5, -0.16]}
        tex={String.raw`\varepsilon`}
        size={FONT_LABEL}
        anchor="middle"
        opacity={OPACITY.fg}
      />
      <Tex
        at={[-0.04, 0.85]}
        tex={String.raw`\sigma`}
        size={FONT_LABEL}
        anchor="middle"
        opacity={OPACITY.fg}
      />
    </Plot>
  )
}

// 06.10.5 Poisson effect: rod with adjustable ν
export function CM_LE_PoissonEffect() {
  const [nu, setNu] = React.useState(0.3)
  const [stretch, setStretch] = React.useState(0.22)
  const epsZ = stretch
  const epsX = -nu * stretch
  const Lhalf = 0.5,
    halfW = 0.22
  const newHalfL = Lhalf * (1 + epsZ)
  const newHalfW = halfW * (1 + epsX)
  const regime = nu >= 0.45 ? 'nearly incompressible' : nu < 0 ? 'auxetic (expands sideways)' : ''

  return (
    <div style={{ maxWidth: 500, margin: '1rem auto' }}>
      <div style={{ display: 'flex', gap: 16 }}>
        <Slider
          label="Stretch"
          value={stretch}
          min={0}
          max={0.4}
          step={0.02}
          onChange={setStretch}
          unit=""
        />
        <Slider label="ν" value={nu} min={-0.95} max={0.49} step={0.01} onChange={setNu} unit="" />
      </div>
      <Plot xRange={[-1.8, 1.8]} yRange={[-0.65, 0.65]} width={500} height={280}>
        <Axes step={1} showGrid={false} showTicks={false} showOrigin={false} />
        <Polyline
          points={[
            [-Lhalf, -halfW],
            [Lhalf, -halfW],
            [Lhalf, halfW],
            [-Lhalf, halfW],
            [-Lhalf, -halfW]
          ]}
          opacity={OPACITY.faint}
          dash="4 3"
          strokeWidth={STROKE_SECONDARY}
        />
        <Polyline
          points={[
            [-newHalfL, -newHalfW],
            [newHalfL, -newHalfW],
            [newHalfL, newHalfW],
            [-newHalfL, newHalfW],
            [-newHalfL, -newHalfW]
          ]}
          opacity={OPACITY.fg}
          strokeWidth={2}
          fillOpacity={0.09}
        />
        <Arrow from={[Lhalf, 0]} to={[newHalfL + 0.12, 0]} opacity={OPACITY.accent} />
        <Arrow from={[-Lhalf, 0]} to={[-newHalfL - 0.12, 0]} opacity={OPACITY.accent} />
        {/* lateral response: sides move in (contraction) or out (auxetic) */}
        <Arrow from={[0, halfW + 0.04]} to={[0, newHalfW]} opacity={OPACITY.dim} head={5} />
        <Arrow from={[0, -halfW - 0.04]} to={[0, -newHalfW]} opacity={OPACITY.dim} head={5} />
        <Tex
          at={[0, -newHalfW - 0.1]}
          tex={String.raw`\varepsilon_x=${epsX.toFixed(3)}`}
          size={FONT_SMALL}
          anchor="middle"
          opacity={OPACITY.dim}
        />
        {regime && (
          <Tex
            at={[0, -0.46]}
            tex={String.raw`\text{${regime}}`}
            size={FONT_SMALL}
            anchor="middle"
            opacity={OPACITY.accent}
          />
        )}
        <Tex
          at={[newHalfL + 0.22, 0.07]}
          tex={String.raw`\varepsilon_z=${epsZ.toFixed(3)}`}
          size={FONT_SMALL}
          anchor="start"
          opacity={OPACITY.accent}
        />
        <Tex
          at={[0, 0.52]}
          tex={String.raw`\nu=${nu.toFixed(2)}`}
          size={FONT_LABEL}
          anchor="middle"
          opacity={OPACITY.fg}
        />
      </Plot>
    </div>
  )
}

